(237, 'Department of Microbiology Event Gallery', '', '', '', '2021-01-25', '2021-01-25', '', '', 'AM,PM', 'AM,PM', '', 0, 0, '', '', NULL, NULL, NULL, 174, '2025-04-25', '', 'Past Event', '', '<div class=\"row\">\r\n<div class=\"col-lg-6 col-md-6 colsm-12\">\r\n<div class=\"card mb-3\"></div>\r\n</div>\r\n</div>\r\n<div class=\"container\">\r\n<div class=\"row mtli-row-clearfix\">\r\n<div class=\"col-xs-12 col-sm-6 col-md-4 sm-text-center mb-30 mb-sm-30\">\r\n<div class=\"team maxwidth400\">\r\n<div class=\"thumb\">\r\n<div class=\"col-xs-12 col-sm-6 col-md-4 sm-text-center mb-30 mb-sm-30\">\r\n<table style=\"width: 779px; height: 685px;\" border=\"1\">\r\n<tbody>\r\n<tr style=\"height: 59px;\">\r\n<td style=\"width: 212px; height: 59px;\">\r\n<h3><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\"><strong>Date</strong></span></h3>\r\n</td>\r\n<td style=\"width: 550px; height: 59px;\">\r\n<h3><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\"><strong>Name of Event</strong></span></h3>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 212px;\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 14pt;\">21st October to 26th October 2024</span></td>\r\n<td style=\"width: 550px;\">\r\n<p>&lt;', 'web-assets/img/event-placeholder.jpg', '', '', '', '', '', 0, '2025-04-25', 1, ''),
(238, 'Alumni Meet- up', '', '', 'Intra-College', '2025-01-11', '2025-01-11', '', '', 'AM,PM', 'AM,PM', '', 19, 0, '', '', NULL, NULL, NULL, 182, '2025-04-30', 'Classroom- 305', 'Past Event', '', '<p style=\"text-align: justify;\">The Economics Department successfully organized an <strong>Alumni Meet</strong> on <strong>11th January 2025 </strong>in <strong>Room No. 305</strong>. The event aimed to foster connections between the department&rsquo;s current&nbsp; students and its esteemed alumni, and to celebrate the achievements and journeys of former&nbsp;<br />students.&nbsp;&nbsp;</p>', 'uploads/Events/copy-1745980261-Alumni-Meet.jpeg', 'uploads/copy-1745980261-Almuni-Meet--11th-January-2025^-(1).pdf', '', '', '', '', 0, '2025-04-25', 1, ''),
(239, 'Celebration of Savitribai Phule Jayanti', '', '', 'Intra-College', '2025-01-06', '2025-01-06', '', '', 'AM,PM', 'AM,PM', '', 19, 0, '', '', NULL, NULL, NULL, 182, '2025-04-30', 'Classroom- 317', 'Past Event', '', '<p style=\"text-align: justify;\">The PTVA\'S Sathaye College (Autonomous), Department of Economics celebrated <strong>Savitribai Phule Jayanti</strong>. The celebration of Savitribai Phule Jayanti was held in Room No. 317 on 6th January 2025, starting at 9:00 AM.</p>', 'uploads/Events/savitribai-1.png', 'uploads/Savitribai-Phule-Jayanti-2025.pdf', '', '', '', '', 0, '2025-04-25', 1, ''),
(240, 'Study Tour to Gwalior', '', '', 'Intra-College', '2024-12-05', '2024-12-10', '', '', 'AM,PM', 'AM,PM', '', 19, 0, '', '', NULL, NULL, NULL, 182, '2025-04-30', 'Gwalior', 'Past Event', '', '<p style=\"text-align: justify;\">The Department of Economics of PTVA&rsquo;s Sathaye College organized a Study Tour from <strong>5th to 10th December 2024</strong>, covering the historically and culturally&nbsp; rich regions of <strong>Gwalior, Jhansi, and Orchha.</strong></p>', 'uploads/Events/gwalior-2.png', 'uploads/Gwailor-report.pdf', '', '', '', '', 0, '2025-04-25', 1, ''),
(241, 'Workshop for Research Methodology', '', '', 'Intra-College', '2024-12-02', '2024-12-02', '', '', 'AM,PM', 'AM,PM', '', 19, 0, '', '', NULL, NULL, NULL, 182, '2025-04-30', '3rd Floor Auditorium', 'Past Event', '', '<p style=\"text-align: justify;\">The Department of Economics of PTVA&rsquo;S Sathaye College had organised <strong>WORKSHOP FOR RESEARCH METHODOLY </strong>on<strong> 2nd December, 2024</strong>. This progam was organised for students of all classes to understand how to perform analysis of Data of any research in depth. The workshop was organised on <strong>&ldquo;Sourcing and Analyzing Data for Economic Research: Best Practices and Strategies.&rdquo;</strong> The <strong>Chief Guest</strong> and <strong>Speaker </strong>of the Programme was <strong>Dr. Shreshti Rawat</strong> a Professor and Reasearcher. She is the Assitant Professor at Meghnad Desai Academy of Economics.</p>', 'uploads/Events/Worshop-on-Research.jpeg', 'uploads/Workshop-Research-Report-2-Dec,-2024.pdf', '', '', '', '', 0, '2025-04-25', 1, ''),
(243, 'Guest lecture on “Budget 2022-Amrit Kal”.', '', '', 'Intra-College', '2022-03-05', '2022-03-05', '', '', 'AM,PM', 'AM,PM', '', 34, 0, '', '', NULL, NULL, NULL, 150, '2025-04-30', '3rd Floor Auditorium', 'Past Event', '', '<p>The Department of Commerce of the college had organized a guest lecture on Budget 2022- Amrit Kal. The lecture was delivered by Mr.Rajesh Bhoite Associate Professor and Head of Department at Anjuman-i-Islam College. Mr.Rajesh Bhoite highlighted students on Various Economic Indicator, Policies announced under various sector, Four Pillar of 2022 Budget were covered.The total attendance for the lecture was 34 students. The attendee students enjoyed it and found it to be useful in their career</p>', 'uploads/Events/2022-05-09-at-11.17.35-AM.jpeg', 'uploads/Budget-2022-Amrit-Kal.pdf', '', '', '', '', 0, '2025-04-25', 1, ''),
(244, 'Guest Lecture On “RESUME BUILDING”', '', '', 'Intra-College', '2022-08-20', '2022-08-20', '', '', 'AM,PM', 'AM,PM', '', 34, 0, '', '', NULL, NULL, NULL, 150, '2025-04-30', 'College Auditorum', 'Past Event', '', '<p>On 20th of August, 2022, at 10.00 a.m. Saturday, the Department of Commerce of P.T.V.A&rsquo;s Sathaye College (Autonomous), Vile Parle organized a lecture on resume building by Mr. Ishwar Jha. He is the former CEO of Zee Entertainment and CIO of Sony Music. He is the<br />multi-award winning personality. In session, he explained the important techniques of building resume during three years of graduation. He also motivates the students to participate in various college activities to build confidence and get hands on experience to organize and execute various activities. A total of 120 students along with 4 faculty member attended the lecture in the Sathaye College&rsquo;s auditorium.</p>', 'uploads/Events/Resume.jpg', 'uploads/Resume-Building-2023.pdf', '', '', '', '', 0, '2025-04-25', 1, ''),
(245, 'Vaanijya Utsav', '', '', 'Intra-College', '2024-12-19', '2024-12-20', '', '', 'AM,PM', 'AM,PM', '', 34, 0, '', '', NULL, NULL, NULL, 150, '2025-04-25', 'College', 'Past Event', '', '<p>Vaanijya Utsav, an annual event organized by the Department of Commerce at Sathaye College, aims to provide students with a platform to explore the realms of commerce, business, and entrepreneurship. The event serves as an interactive space for students to engage with industry professionals, enhance their knowledge, and showcase their entrepreneurial skills. This year&rsquo;s Vaanijya Utsav saw participation from various sectors, offering a holistic view of the commercial world.</p>', 'uploads/Events/VANIJYA_page-0001.jpg', 'uploads/copy-1745558055-Report-on-Vaanijya-Utsav.pdf', '', '', '', '', 0, '2025-04-25', 1, ''),
(246, 'Mathspire', '', '', 'Intra-College', '2024-12-19', '2024-12-20', '', '', 'AM,PM', 'AM,PM', '', 38, 0, '', '', NULL, NULL, NULL, 198, '2025-04-25', 'Sathaye College, Room No. 108', 'Past Event', '', '<p>The annual event Mathspire of Department of Mathematics, PTVA&rsquo;s Sathaye Collge was<br />held on 19th and 20th December 2024 from 11:00 am to 4:00 pm in Room No. 108.</p>', 'uploads/Events/copy-1745559878-IMG-20250425-WA0002_1.jpg', 'uploads/Mathspire-report.pdf', '', '', '', '', 0, '2025-04-25', 1, ''),
(247, 'Advance Learner Session', '', '', 'Intra-College', '2024-11-28', '2024-11-28', '', '', 'AM,PM', 'AM,PM', '', 32, 0, '', '', NULL, NULL, NULL, 173, '2025-04-25', 'PTVA’s Sathaye College (Autonomous)', 'Past Event', '', '<p style=\"text-align: justify;\">On Thursday, 28th November, 2024, at 9.30 a.m. to 10.30 a.m. a highly informative and engaging session on Advance Learner was organized for B. Com and BAF students at PTVA&rsquo;s Sathaye College (Autonomous). The event aimed to enhance the skills, knowledge in their subjects of Accountancy and Plan for advance study in Accountancy &amp; related subjects.</p>', 'uploads/Events/copy-1745558242-Advance-Learner-Session-photo-1.jpeg', 'uploads/Advance-Learner.-pdf.pdf', '', '', '', '', 0, '2025-04-25', 1, ''),
(248, 'Career and Placement Session', '', '', 'Intra-College', '2024-11-28', '2024-11-28', '', '', 'AM,PM', 'AM,PM', '', 32, 0, '', '', NULL, NULL, NULL, 173, '2025-04-25', '', 'Past Event', '', '<p style=\"text-align: justify;\">On Thursday, 28th November, 2024, at 10.30 a.m. to 11.30 a.m. a highly informative and engaging session on Career and Placement was organized for B. Com and BAF students at PTVA&rsquo;s Sathaye College (Autonomous). The event aimed to provide valuable insights into the world of career opportunities and placements, empowering students to make informed decisions about their future.</p>', 'uploads/Events/copy-1745558488-Career-and-Placement-Session-photo-2.jpeg', 'uploads/Career-&-Placement-Report.pdf', '', '', '', '', 0, '2025-04-25', 1, ''),
(249, 'AD-MAGINATION MARATHON', '', '', '', '2024-09-14', '2024-09-14', '', '', 'AM,PM', 'AM,PM', '', 34, 0, '', '', NULL, NULL, NULL, 150, '2025-04-25', '', 'Past Event', '', '<p>The Ad-Magination Marathon took place on September 14, 2024, at Parle Tilak Vidyalaya Association&rsquo;s Sathaye College, organized by the department of commerce. The event commenced at 10:00 am and concluded at 11:30 am at ground floor auditorium. Over 6 teams, consisting of maximum 7 students each, participated in the marathon. The event saw enthusiastic participation from students across different departments. It began with an introduction of the chief guest, Dr. Madhav Rajwade, who was honored by Mr. Gautam Maske, the head of the commerce department. Dr. Madhav Rajwade sir delivered an insightful speech on the significance of creativity and innovation in advertising. Following his address, the judging panel was introduced, consisting of Mr. Gajendra Deoda, the BMM course coordinator, Ms. Utkarsha Ippar, the BMS course coordinator, and Mr. Gautam Maske, head, of commerce department. All three guests were also felicitated by Mr. Maske. The event was attended by almost 60 interest', 'uploads/Events/Picture1.jpg', 'uploads/copy-1745558786-AD-MAGINATION-MARATHON.pdf', '', '', '', '', 0, '2025-04-25', 1, ''),
(251, 'VRIKSHATANAM (वृक्षाटनम्)', '', '', '', '2024-08-20', '2024-08-20', '', '', 'AM,PM', 'AM,PM', '', 29, 0, '', '', NULL, NULL, NULL, 156, '2025-04-25', 'Sathaye College Campus', 'Past Event', '', '<p style=\"text-align: justify;\">On the occasion of <strong>\'Sanskrit Day\'</strong> which is celebrated on <strong>\'Narali Poornima\'</strong>, the Department of Sanskrit, Sathaye College, organized an insightful and educational program called <strong>\'</strong><strong>वृक्षाटनम्\'</strong> on <strong>Tuesday, 20th August 2024</strong>. Total 35 interdisciplinary students participated in this event. This unique event aimed to blend the beauty of nature with the richness of Sanskrit literature, offering students an opportunity to explore the college garden while learning about the diverse plant life and their significance in Sanskrit texts.</p>', 'uploads/Events/WhatsApp-Image-2024-08-26-at-12.54.41_cbb1c0e4.jpg', 'uploads/VRIKSHATANAM-20-Aug.-24.pdf', '', '', '', '', 0, '2025-04-25', 1, ''),
(252, 'DHRUVA SANSKRIT COMPETITION', '', '', 'Inter-College', '2024-09-28', '2024-09-28', '', '', 'AM,PM', 'AM,PM', '', 29, 0, '', '', NULL, NULL, NULL, 156, '2025-04-27', 'V. G. Vaze College', 'Past Event', '', '<p style=\"text-align: justify;\"><span style=\"color: #236fa1;\">V. G. Vaze College, Mulund, recently organized the <strong>Dhruva Sanskrit Mahotsav</strong>, an intercollegiate event designed to celebrate and promote Sanskrit language and culture while encouraging artistic expression among students on <strong>28<sup>th</sup> September 2024</strong>. The event saw participation from 16 schools and 13 colleges, bringing together students from various academic backgrounds to compete in a range of creative and intellectual activities...</span></p>\r\n<p style=\"text-align: justify;\"><strong><span style=\"color: #ba372a;\">Solo Singing - 1st Rank</span></strong></p>\r\n<p style=\"text-align: justify;\"><strong><span style=\"color: #ba372a;\">Exhibition - 1st Rank</span></strong><span style=\"color: #236fa1;\"></span></p>', 'uploads/Events/copy-1745560560-1.jpg', 'uploads/DHRUVA-28-Sep.-24.pdf', '', '', '', '', 0, '2025-04-25', 1, ''),
(253, 'Guest Lecture on Applications of Mathematics', '', '', 'Intra-College', '2024-08-10', '2024-08-10', '', '', 'AM,PM', 'AM,PM', '', 38, 0, '', '', NULL, NULL, NULL, 198, '2025-04-25', 'Sathaye College, Room No. 115', 'Past Event', '', '<p>A guest lecture on Applications of Mathematics by Mr. Salil Sawarkar from C.H.M College was organized by Department of Mathematics, PTVA&rsquo;s Sathaye College.</p>', 'uploads/Events/IMG_4925_SalilSir.jpg', 'uploads/Guest-Lecture-on-Applications-of-Mathematics.pdf', '', '', '', '', 0, '2025-04-25', 1, ''),
(254, 'A VISIT TO IIT BOMBAY', '', '', '', '2024-12-18', '2024-12-18', '', '', 'AM,PM', 'AM,PM', '', 29, 0, '', '', NULL, NULL, NULL, 156, '2025-04-25', 'IITB', 'Past Event', '', '<p style=\"text-align: justify;\"><span style=\"color: #472a02;\">On <strong>Wednesday</strong>, <strong>December 18, 2024</strong> the Sanskrit department of Sathaye College organized an educational visit to IIT Bombay. IITB had organized a tech fest in which they had various events like science exhibition, space exhibition, seminar and lectures on cutting edge technology and electronics. The main reason for the students to visit the tech fest was to introduce students to the computer linguistic course which is soon going to be part of the third-year curriculum for our students.</span></p>', 'uploads/Events/copy-1745561001-3.jpg', 'uploads/IIT-BOMBAY-VISIT-18-Dec.-24.docx', '', '', '', '', 0, '2025-04-25', 1, ''),
(255, 'SPOKEN SANSKRIT WORKSHOP', '', '', '', '2025-01-03', '2025-01-09', '', '', 'AM,PM', 'AM,PM', '', 29, 0, '', '', NULL, NULL, NULL, 156, '2025-04-25', 'Third Floor Auditorium, Sathaye College (Autonomous)', 'Past Event', '', '<p style=\"text-indent: 36pt; text-align: justify;\"><span lang=\"EN-US\"><span style=\"color: #440241;\">The event <b>&lsquo;Spoken Sanskrit&rsquo;</b> was conducted from <b>January 3, 2025, to January 9, 2025</b>, between 1:00 PM and 3:00 PM daily. This week-long event aimed at celebrating and promoting linguistic diversity while emphasizing the importance of language learning and preservation. Various activities, workshops, and discussions were conducted throughout the week, attracting language enthusiasts from different backgrounds.....</span></span></p>', 'uploads/Events/copy-1745561316-1.jpg', 'uploads/SPOKEN-SANSKRIT-WORKSHOP-3-Jan.-to-9-Jan.-25-(1).docx', '', '', '', '', 0, '2025-04-25', 1, ''),
(256, 'Seminar on Applications of Mathematics', '', '', 'Intra-College', '2024-08-08', '2024-08-08', '', '', 'AM,PM', 'AM,PM', '', 38, 0, '', '', NULL, NULL, NULL, 198, '2025-04-25', 'Sathaye College, Room No. 207', 'Past Event', '', '<p>Department of Mathematics had organized seminars for the students on 7th August 2024.&nbsp;</p>', 'uploads/Events/IMG_4894_Seminar_1.jpg', 'uploads/Seminar-Student-report.pdf', '', '', '', '', 0, '2025-04-25', 1, ''),
(257, 'The Roll of Gender in Stress and  Stress Management', '', '', '', '2025-01-15', '2025-01-15', '', '', 'AM,PM', 'AM,PM', '', 38, 0, '', '', NULL, NULL, NULL, 198, '2025-04-25', 'Sathaye College, Room No. 207', 'Past Event', '', '<p>A guest lecture on &ldquo;The Role of Gender in Stress and Stress Management&rdquo; by Ms. Anuja Pingale, Assistant Professor from Department of Psychology was organized by Department of Mathematics.</p>', 'uploads/Events/Gender1_page-0001.jpg', 'uploads/Gender-Stress.pdf', '', '', '', '', 0, '2025-04-25', 1, ''),
(258, 'Visit to 8 Maharashtra Girls Battalion NCC, Mumbai', '', '', '', '2024-08-22', '2024-08-22', '', '', 'AM,PM', 'AM,PM', '', 61, 0, '', '', NULL, NULL, NULL, 397, '2025-04-25', '8 Maharashtra Girls Battalion NCC, Mumbai', 'Past Event', '', '<p>On 22nd August 2024, a group of seven students, accompanied by<br />faculty of Department of Defence studies, visited the 8 Maharashtra Girls Battalion<br />NCC, Mumbai, as part of a field project aimed at providing practical exposure to<br />the training and organizational structure of the National Cadet Corps (NCC).<br />The visit began with a briefing by Battalion Officers, who introduced the students<br />to the objectives, structure, and activities of the NCC. The officers elaborated on<br />the role of NCC in nation-building, leadership development, and community<br />service and explained the administrative work of battalion.<br />The students actively participated in discussions, asked insightful questions, and<br />gained a deeper appreciation for the values instilled through NCC training. The<br />visit proved to be an enriching experience, fostering a sense of discipline,<br />responsibility, and patriotism among the students.</p>', 'uploads/Events/1740829192111.jpg', 'uploads/copy-1745564606-Defence-Studies-Departmental-Activity-Report.docx', '', '', '', '', 0, '2025-04-25', 1, ''),
(259, 'Visit to Kanheri Caves for Judging Distance Practice Session', '', '', '', '2024-09-05', '2024-09-05', '', '', 'AM,PM', 'AM,PM', '', 61, 0, '', '', NULL, NULL, NULL, 397, '2025-04-25', 'National Park (Borivali) , Mumbai', 'Past Event', '', '<p>On 5th September 2024, a group of 07 Defence Studies students,<br />accompanied by 02 faculty members, visited Kanheri Caves, Mumbai, for a field<br />project focused on judging distance&mdash;a crucial skill in military training and tactical<br />operations. The objective of this visit was to provide students with practical<br />exposure to estimating distances under varied terrain conditions.<br />The session began with a briefing on the importance of judging distance in<br />military operations, reconnaissance, and combat scenarios. Faculty members<br />explained different methods, including the unit of measure method, appearance<br />method, and bracketing technique, which help in accurately assessing distances in<br />different environments.<br />Students were divided into small groups and given specific targets at<br />varying distances to esti</p>', 'uploads/Events/1740829348148.jpg', 'uploads/copy-1745564598-Defence-Studies-Departmental-Activity-Report.docx', '', '', '', '', 0, '2025-04-25', 1, ''),
(260, 'Beach Clean-Up Drive at Juhu Beach', '', '', '', '2024-09-18', '2024-09-18', '', '', 'AM,PM', 'AM,PM', '', 61, 0, '', '', NULL, NULL, NULL, 397, '2025-04-25', 'Juhu Beach, Vile Parle (West)', 'Past Event', '', '<p>On 18th September 2024, the Department of Defence Studies, Sathaye<br />College, organized a beach clean-up drive at Juhu Beach, Mumbai, as part of their<br />commitment to environmental sustainability and community service. The event<br />aimed to raise awareness about the growing issue of marine pollution and the<br />importance of protecting coastal ecosystems.<br />A group of 20 students, along with faculty members, actively participated in<br />the clean-up. Armed with gloves, bags, and other necessary equipment, students<br />worked in teams to collect waste scattered along the beach. The initiative not only<br />focused on removing waste but also on sorting recyclables and educating local<br />residents and tourists about the importance of reducing plastic usage and disposing<br />waste responsibly.<br />Throughout the drive, students exhibited great teamwork and a strong sense<br />of social responsibility. The event concluded with a discussion on the importance<br />of long', 'uploads/Events/WhatsApp-Image-2025-03-01-at-9.09.52-PM-(2).jpeg', 'uploads/copy-1745564591-Defence-Studies-Departmental-Activity-Report.docx', '', '', '', '', 0, '2025-04-25', 1, ''),
(261, 'Visit to Traffic Control Station', '', '', '', '2024-09-20', '2024-09-20', '', '', 'AM,PM', 'AM,PM', '', 61, 0, '', '', NULL, NULL, NULL, 397, '2025-04-25', 'Traffic Control Station, Worli, Mumbai', 'Past Event', '', '<p>On 20th September 2024, a group of 05 Defence Studies students visited the<br />Worli Traffic Control Station, Mumbai, as part of a field project aimed at<br />understanding urban traffic management, surveillance systems, and security<br />coordination. The visit provided students with practical insights into how modern<br />traffic control centers function and their role in ensuring public safety.<br />The visit began with a briefing by traffic officials, who explained the<br />structure and operations of the control station. Students were introduced to<br />advanced traffic monitoring systems, CCTV surveillance, and automated signal<br />management used to regulate vehicular movement and prevent congestion.<br />Officials also discussed the integration of Artificial Intelligence (AI) and data<br />analytics in traffic management to enhance efficiency and law enforcement.</p>\r\n<p>A key highlight of the visit was a live demonstration of real-time traffic<br />monitoring. Students ob', 'uploads/Events/IMG_9675.JPG', 'uploads/copy-1745564566-Defence-Studies-Departmental-Activity-Report.docx', '', '', '', '', 0, '2025-04-25', 1, ''),
(262, 'Seminar on Sustainability', '', '', 'Inter-College', '2024-09-29', '2024-09-29', '', '', 'AM,PM', 'AM,PM', '', 0, 0, '', '', NULL, NULL, NULL, 397, '2025-04-25', 'Sathaye College Ground floor Auditorium, Vile Parle (East)', 'Past Event', '', '<p>The Department of Defence Studies, Sathaye College, Mumbai,<br />organized a seminar on Sustainability on 29th September 2024, featuring Dr.<br />Sachin Shigwan, popularly known as &amp;quot;The Solar Man of India,&amp;quot; as the keynote<br />speaker. The seminar aimed to highlight the importance of sustainable energy<br />solutions and their significance in national security, environmental conservation,<br />and energy independence.<br />Dr. Shigwan then delivered an engaging presentation on solar energy innovations,<br />focusing on how renewable energy can enhance self-sufficiency and reduce<br />dependency on conventional resources. He provided real-world examples of solar<br />energy applications in rural and urban settings, showcasing his work in promoting<br />sustainable solutions across India.<br />Dr. Shigwan also encouraged students to explore careers in renewable<br />energy and sustainability, linking it to national development and security<br />strategies.<br />The s', 'web-assets/img/event-placeholder.jpg', '', '', '', '', '', 0, '2025-04-25', 1, ''),
(263, 'Seminar on Sustainability', '', '', 'Inter-College', '2024-09-29', '2024-09-29', '', '', 'AM,PM', 'AM,PM', '', 61, 0, '', '', NULL, NULL, NULL, 397, '2025-04-25', 'Sathaye College ground floor Auditorium, Vile Parle (East)', 'Past Event', '', '<p>The Department of Defence Studies, Sathaye College, Mumbai,<br />organized a seminar on Sustainability on 29th September 2024, featuring Dr.<br />Sachin Shigwan, popularly known as &amp;quot;The Solar Man of India,&amp;quot; as the keynote<br />speaker. The seminar aimed to highlight the importance of sustainable energy<br />solutions and their significance in national security, environmental conservation,<br />and energy independence.<br />Dr. Shigwan then delivered an engaging presentation on solar energy innovations,<br />focusing on how renewable energy can enhance self-sufficiency and reduce<br />dependency on conventional resources. He provided real-world examples of solar<br />energy applications in rural and urban settings, showcasing his work in promoting<br />sustainable solutions across India.<br />Dr. Shigwan also e</p>', 'uploads/Events/WhatsApp-Image-2025-03-01-at-5.10.31-PM.jpeg', 'uploads/copy-1745564548-Defence-Studies-Departmental-Activity-Report.docx', '', '', '', '', 0, '2025-04-25', 1, ''),
(264, 'Seminar on Awareness and Promotion of Tourism in Maharashtra', '', '', '', '2024-12-10', '2024-12-10', '', '', 'AM,PM', 'AM,PM', '', 61, 0, '', '', NULL, NULL, NULL, 397, '2025-04-25', 'Room No. 13, Department of Geography, Sathaye college', 'Past Event', '', '<p>On 10th December 2024, a seminar on &amp;quot;Awareness and Promotion of<br />Tourism in Maharashtra&amp;quot; was organized by the Department of Geography and the<br />Department of Defence Studies, in association with the MMRDA. The seminar</p>\r\n<p>aimed to highlight the potential of tourism in Maharashtra and its impact on the<br />state&amp;#39;s economy and cultural heritage.<br />The session was led by Ronit Purswani, the Project Coordinator at PDC<br />Events. He shared his insights on the evolving tourism landscape in Maharashtra,<br />emphasizing the need for strategic marketing and infrastructure development to<br />attract both domestic and international tourists. He also discussed various<br />initiatives by the government and private sectors to promote eco-tourism,<br />adventure tourism, and cultural tourism.<br />The seminar was highly informative, with participants gaining a deeper<br />understanding of how tourism can be a key driver for sustainable economic<br />gr', 'uploads/Events/IMG_2215.JPG', 'uploads/copy-1745564539-Defence-Studies-Departmental-Activity-Report.docx', '', '', '', '', 0, '2025-04-25', 1, ''),
(265, 'Seminar on Geopolitical Dynamics and National Security: A Career Perspective', '', '', 'Inter-College', '2025-01-15', '2025-01-15', '', '', 'AM,PM', 'AM,PM', '', 0, 0, '', '', NULL, NULL, NULL, 397, '2025-04-25', 'Sathaye College Auditorium, Vile Parle (East)', 'Past Event', '', '<p>On the occasion of Army Day (15th January 2025), the Department of<br />Defence Studies, organized a guest lecture on the topic &amp;quot;Geopolitical Dynamics<br />and National Security: A Career Perspective.&amp;quot; The session was delivered by Col.<br />Avinash Rayarikar, an experienced military professional, who provided valuable<br />insights into the complex inter linkages between global geopolitics, national<br />security, and career opportunities in defense and strategic affairs.<br />The event commenced with a welcome address emphasizing the significance<br />of Army Day in honoring the sacrifices and contributions of the Indian Army. Col.<br />Rayarikar&amp;#39;s lecture focused on key geopolitical challenges, including border<br />security, regional conflicts, emerging global threats, and India&amp;#39;s defense strategy.<br />He explained how shifting power dynamics affect national security policies and<br />defense preparedness.<br />Col. Rayarikar provided students w', 'web-assets/img/event-placeholder.jpg', '', '', '', '', '', 0, '2025-04-25', 1, ''),
(266, 'Seminar on & Geopolitical Dynamics and National Security: A Career perspective', '', '', 'Inter-College', '2025-01-15', '2025-01-15', '', '', 'AM,PM', 'AM,PM', '', 61, 0, '', '', NULL, NULL, NULL, 397, '2025-04-25', 'Sathaye College Auditorium, Vile Parle (East)', 'Past Event', '', '<p>On the occasion of Army Day (15th January 2025), the Department of<br />Defence Studies, organized a guest lecture on the topic &amp;quot;Geopolitical Dynamics<br />and National Security: A Career Perspective.&amp;quot; The session was delivered by Col.<br />Avinash Rayarikar, an experienced military professional, who provided valuable<br />insights into the complex inter linkages between global geopolitics, national<br />security, and career opportunities in defense and strategic affairs.<br />The event commenced with a welcome address emphasizing the significance<br />of Army Day in honoring the sacrifices and contributions of the Indian Army. Col.<br />Rayarikar&amp;#39;s lecture focused on key geopolitical challenges, including border<br />security, regional conflicts, emerging global threats, and India&amp;#39;s defense strategy.<br />He explained how shifting power dynamics affect national security policies and<br />defense preparedness.<br />Col. Rayarikar provided students w', 'uploads/Events/WhatsApp-Image-2025-03-01-at-7.37.33-PM.jpeg', 'uploads/copy-1745564528-Defence-Studies-Departmental-Activity-Report.docx', '', '', '', '', 0, '2025-04-25', 1, ''),
(267, 'Defence Studies Exhibition', '', '', '', '2024-12-12', '2024-12-12', '', '', 'AM,PM', 'AM,PM', '', 61, 0, '', '', NULL, NULL, NULL, 397, '2025-04-25', 'Parle Tilak Marathi Vidyalay, Ground. Vile Parle East', 'Past Event', '', '<p>The Department of Defence Studies successfully organized an Exhibition on<br />Static Models of the Army, Navy, and Air Force on the occasion of NCC Day. The<br />event commenced at 9:00 AM and witnessed enthusiastic participation from<br />students from school and college, faculty members, and defence aspirants.<br />The exhibition aimed at promoting awareness about careers in Defence<br />Studies by showcasing detailed static models of military equipment, ships, aircraft,<br />and armored vehicles. The exhibits provided insights into the functioning of the<br />Indian Army, Navy, and Air Force, giving attendees a closer look at the<br />technological advancements in defence.<br />The event successfully ignited interest among young minds and served as an<br />interactive platform for career guidance. The exhibition concluded on a positive<br />note, encouraging students to explore the dynamic field of Defence Studies and<br />consider a future in the armed forces. The initiative wa', 'uploads/Events/WhatsApp-Image-2025-03-01-at-5.50.03-PM-(2).jpeg', 'uploads/copy-1745564519-Defence-Studies-Departmental-Activity-Report.docx', '', '', '', '', 0, '2025-04-25', 1, ''),
(268, 'Pinkathon', '', '', '', '2024-12-15', '2024-12-15', '', '', 'AM,PM', 'AM,PM', '', 61, 0, '', '', NULL, NULL, NULL, 397, '2025-04-25', 'Inorbit Mall, Malad (West)', 'Past Event', '', '<p>Students from the Department of Defence Studies, Sathaye College,<br />enthusiastically participated in Pinkathon 2024. The marathon, aimed at<br />promoting women&rsquo;s health and fitness, saw an overwhelming response from<br />participants across various age groups.<br />The students displayed great energy and determination, running alongside<br />fitness enthusiasts, social activists, and professionals. Their participation reflected<br />the core values of discipline, endurance, and physical fitness&mdash;essential attributes<br />in the field of Defence Studies. The event served as an important platform to raise<br />awareness about women&rsquo;s health issues, especially breast cancer, and the<br />significance of regular health check-ups.</p>\r\n<p>Many successfully completed the marathon, demonstrating their<br />commitment to fitness and social causes. Their participation also highlighted the<br />department&rsquo;s focus on holistic development and leadership skills.<br />P', 'uploads/Events/WhatsApp-Image-2025-03-01-at-8.58.10-PM-(1).jpeg', 'uploads/copy-1745564511-Defence-Studies-Departmental-Activity-Report.docx', '', '', '', '', 0, '2025-04-25', 1, ''),
(269, 'Solar Light Installation under Community Engagement Program', '', '', '', '2025-01-20', '2025-01-21', '', '', 'AM,PM', 'AM,PM', '', 61, 0, '', '', NULL, NULL, NULL, 397, '2025-04-25', 'Thane Slum and Ogada Village, Palghar', 'Past Event', '', '<p>The Department of Defence Studies, Sathaye College in collaboration with<br />the Green India Initiative, organized a Students&rsquo; Community Engagement Program<br />on 20th and 21st January 2025. The program aimed at installing solar lights to<br />enhance sustainable energy access in underprivileged areas. A total of 25 solar<br />street lights each were installed at the Thane slum and Ogada village in Palghar,<br />significantly improving community safety and energy availability.<br />On 20th January, students visited Thane slum, where they engaged with<br />local residents, explaining the importance of renewable energy. The installation<br />process was carried out with the help of Green India Initiative experts, ensuring<br />that the solar units were properly set up and maintained.<br />On 21st January, the team proceeded to Ogada village, Palghar, where they<br />installed another 25 solar street lights. This initiative benefited community with<br />limited access to electr', 'uploads/Events/WhatsApp-Image-2025-01-21-at-6.10.54-PM.jpeg', 'uploads/copy-1745564501-Defence-Studies-Departmental-Activity-Report.docx', '', '', '', '', 0, '2025-04-25', 1, ''),
(270, 'India Week 2024', '', '', '', '2024-08-19', '2024-08-24', '', '', 'AM,PM', 'AM,PM', '', 0, 0, '', '', NULL, NULL, NULL, 203, '2025-04-25', 'Sathaye College', 'Past Event', '', '<p><span style=\"font-weight: 400;\">The Department of Ancient Indian Culture and Buddhist studies along with Social Science association of PTVA&rsquo;s Sathaye College (Autonomous) organised an event, &lsquo;India week 2024&rsquo; from 19th August to 24th August 2024 on the occasion of Jainacharya Buddhisagarji\'s &lsquo;150th Birth Anniversary&rsquo; and also his &lsquo;100th Death Anniversary&rsquo;. As India Week celebration focuses on celebrating India\'s many cultures and their values in an effective way to create unity through diversity, the Department of Ancient Indian Culture and Buddhist Studies celebrated the diverse cultures of India through competitions which proved to be an enriching and engaging way to promote cultural awareness, education, and creativity.&nbsp;&nbsp;</span></p>', 'uploads/Events/IMG20240905105733.jpg', '', '', '', '', '', 0, '2025-04-25', 1, ''),
(271, 'India Week 2024', '', '', 'Inter-College', '2024-08-19', '2024-08-24', '', '', 'AM,PM', 'AM,PM', '', 0, 0, '', '', NULL, NULL, NULL, 203, '2025-04-25', 'Sathaye College', 'Past Event', '', '<p><span style=\"font-weight: 400;\">The Department of Ancient Indian Culture and Buddhist studies along with Social Science association of PTVA&rsquo;s Sathaye College (Autonomous) organised an event, &lsquo;India week 2024&rsquo; from 19th August to 24th August 2024 on the occasion of Jainacharya Buddhisagarji\'s &lsquo;150th Birth Anniversary&rsquo; and also his &lsquo;100th Death Anniversary&rsquo;. As India Week celebration focuses on celebrating India\'s many cultures and their values in an effective way to create unity through diversity, the Department of Ancient Indian Culture and Buddhist Studies celebrated the diverse cultures of India through competitions which proved to be an enriching and engaging way to promote cultural awareness, education, and creativity.&nbsp;&nbsp;</span></p>', 'uploads/Events/copy-1745566209-IMG20240905105733.jpg', '', '', '', '', '', 0, '2025-04-25', 1, ''),
(272, 'India Week 2024-25', '', '', 'Inter-College', '2024-08-19', '2024-08-24', '09:00', '05:00', 'AM,PM', 'AM,PM', 'PTVA\'s Sathaye College (Autonomous) Department of AIC and Archaeology', 15, 0, '', '', NULL, NULL, NULL, 246, '2026-04-09', '', 'Past Event', '', '<p><span style=\"font-weight: 400;\">The Department of Ancient Indian Culture and Buddhist studies along with Social Science association of PTVA&rsquo;s Sathaye College (Autonomous) organised an event, &lsquo;India week 2024&rsquo; from 19th August to 24th August 2024 on the occasion of Jainacharya Buddhisagarji\'s &lsquo;150th Birth Anniversary&rsquo; and also his &lsquo;100th Death Anniversary&rsquo;. As India Week celebration focuses on celebrating India\'s many cultures and their values in an effective way to create unity through diversity, the Department of Ancient Indian Culture and Buddhist Studies celebrated the diverse cultures of India through competitions which proved to be an enriching and engaging way to promote cultural awareness, education, and creativity.&nbsp;&nbsp;</span></p>', 'uploads/Events/copy-1745569293-IMG20240905105733.jpg', '', NULL, NULL, 'null', '[{}]', 0, '2025-04-25', 1, ''),
(273, 'Visit to Maharahshtra Legislative Assembly', '', '', 'Intra-College', '2023-07-21', '2023-07-21', '', '', 'AM,PM', 'AM,PM', '', 27, 0, '', '', NULL, NULL, NULL, 159, '2025-04-25', 'Maharashtra Vidhan Bhavan', 'Past Event', '', '<p><strong>Visit to Vidhan Bhavan (Monsoon Session 21<sup>st</sup> July 2023)</strong></p>\r\n<p>The Department of Political science organised one-day visit to Vidhan Bhavan for attending the Monsoon session of Maharashtra Legislature on Friday 21<sup>st</sup> July 2023. The educational visit was organised to sensitize students of Political Science towards the actual conduct of legislature business of the house. The students spent one hour in Vidhan Sabha. In Vidhan Sabha students got to see the veteran MLA and Deputy CM of Maharashtra, Devendra Fadanvis answering the House on issue such as air connectivity and connecting Maharashtra&rsquo;s major cities with air-routes. Another one-hour session was spent in Vidhan Parishad where the leader of opposition in Vidhan Parishad Shri Ambadas Danave was seen raising forcefully the issue of farmers distress in Maharashtra. Apart from this, students heard MLAs such as Shri. Aditya Thackeray, Ashok Chavan, Gulabrao Patil, Sunil Prabhu, Praniti Shi', 'web-assets/img/event-placeholder.jpg', '', '', '', '', '', 0, '2025-04-25', 1, ''),
(274, 'Socio - Cultural programme', '', '', 'Intra-College', '2024-08-23', '2024-08-23', '', '', 'AM,PM', 'AM,PM', '', 30, 0, '', '', NULL, NULL, NULL, 372, '2025-04-26', 'Ground Floor, Auditorium (Sathaye college)', 'Past Event', '', '<p>The Socio-Cultural Programme of Sociology -2024</p>', 'uploads/Events/WhatsApp-Image-2025-04-24-at-12.23.10-(3).jpeg', 'uploads/Socio--Cultural-Event-2024-2025-(Sociology).docx', '', '', '', '', 0, '2025-04-26', 1, ''),
(275, 'Art Competition', '', '', 'Intra-College', '2024-08-20', '2024-08-20', '', '', 'AM,PM', 'AM,PM', '', 30, 0, '', '', NULL, NULL, NULL, 372, '2025-04-26', '3 rd Floor Auditorium', 'Past Event', '', '<p>The Department of Sociology had organized Art Competition under India Week in 2024.</p>', 'uploads/Events/WhatsApp-Image-2025-04-24-at-12.40.55-(3).jpeg', 'uploads/Social-Science-Association--Arts-Competition-2024.docx', '', '', '', '', 0, '2025-04-26', 1, ''),
(276, 'Elocution Competition', '', '', 'Intra-College', '2024-08-23', '2024-08-23', '', '', 'AM,PM', 'AM,PM', '', 30, 0, '', '', NULL, NULL, NULL, 372, '2025-04-26', 'Ground Floor Auditorium', 'Past Event', '', '<p>The Department of Sociology had organized Elocution Competiton merge with Socio- cultural programme of Sociology on 23rd August 2024.</p>', 'uploads/Events/WhatsApp-Image-2025-04-17-at-08.34.59.jpeg', 'uploads/Social-Science-Association--Elocution-Competition-2024-(Sociology).docx', '', '', '', '', 0, '2025-04-26', 1, ''),
