(278, 'दसरोत्सव', '', '', 'Inter-College', '2024-10-21', '2024-10-21', '', '', 'AM,PM', 'AM,PM', '', 59, 0, '', '', NULL, NULL, NULL, 414, '2025-04-30', 'साठये महाविद्यालय', 'Past Event', '', '<p>दसरोत्सव -</p>\r\n<p>दसऱ्याच्या शुभ मुहूर्तावर \'दसरोत्सव\' ह्या कार्यक्रमाचे आयोजन दरवर्षी केले जाते. ह्या दिवशी विविध ग्रंथांचे प्रदर्शन सर्व विद्यार्थ्यांसाठी मांडले जाते. मराठी वाङ्मय मंडळाच्या अनेक अभिनव उपक्रमांपैकी हा एक महत्त्वाचा उपक्रम असतो.</p>', 'web-assets/img/event-placeholder.jpg', 'uploads/copy-1745646486-दसरोत्सव-१-.pdf', '', '', '', '', 0, '2025-04-26', 1, ''),
(279, 'International Women\'s Day', '', '', 'Intra-College', '2024-03-08', '2024-03-08', '', '', 'AM,PM', 'AM,PM', '', 30, 0, '', '', NULL, NULL, NULL, 372, '2025-04-26', '118', 'Past Event', '', '<p>The Department of Sociology celebrated International women\'s Day, remembering great women\'s of India.</p>', 'uploads/Events/WhatsApp-Image-2025-04-24-at-15.07.22-(1).jpeg', 'uploads/International-Women-day-celebration-report-2025..docx', '', '', '', '', 0, '2025-04-26', 1, ''),
(280, 'Free health check up camp', '', '', 'Intra-College', '2025-01-19', '2025-01-19', '', '', 'AM,PM', 'AM,PM', '', 30, 0, '', '', NULL, NULL, NULL, 372, '2025-04-26', 'Jogeshwari west', 'Past Event', '', '<p>The Department of Sociology had organized Free health check up camp for slum dwellers in collaboration with Sutantra narayani seva trust NGO in Andheri.</p>', 'uploads/Events/WhatsApp-Image-2025-04-24-at-14.58.09-(1).jpeg', 'uploads/Field-visit-in-collaboration-with-an-NGO-2025.docx', '', '', '', '', 0, '2025-04-26', 1, ''),
(281, 'Field Visit at kolhapur', '', '', 'Intra-College', '2025-02-08', '2025-02-09', '', '', 'AM,PM', 'AM,PM', '', 30, 0, '', '', NULL, NULL, NULL, 372, '2025-04-26', 'Kolhapur', 'Past Event', '', '<p>The Department of Sociology had conducted a field visit in kolhapur at panhala fort with a professional guide to make the students aware about the historical places and its value.</p>', 'uploads/Events/WhatsApp-Image-2025-04-24-at-14.45.48-(2).jpeg', 'uploads/Kolhapur-field-visit-2025-Report.docx', '', '', '', '', 0, '2025-04-26', 1, ''),
