(283, 'Synergy', '', '', 'Inter-College', '2024-12-14', '2024-12-16', '', '', 'AM,PM', 'AM,PM', '', 51, 0, '', '', NULL, NULL, NULL, 398, '2025-04-26', 'College campus', 'Past Event', '', '<p>Synergy - an inter - college event culmination of activities like sport, theatre, music, dance and many more. it a platform which gives opportunities from diverse background.&nbsp;&nbsp;</p>', 'web-assets/img/event-placeholder.jpg', 'uploads/copy-1745653629-REPORT.pdf', '', '', '', '', 0, '2025-04-26', 1, ''),
(284, 'Field Visit at Palghar', '', '', 'Intra-College', '2024-10-19', '2024-10-19', '', '', 'AM,PM', 'AM,PM', '', 30, 0, '', '', NULL, NULL, NULL, 139, '2025-05-14', 'WADA, Palghar', 'Past Event', '', '<p>The Department of Sociology had conducted field visit at wada, palghar.</p>', 'uploads/Events/WhatsApp-Image-2025-04-24-at-13.16.29-(1).jpeg', 'uploads/Field-Visit---PALGHAR-,-WADA--2024(Sociology).docx', '', '', '', '', 0, '2025-04-26', 1, ''),
(285, 'INTERDICIPLINARY LECTURE ON MANUSCRIPTOLOGY', '', '', '', '2025-01-18', '2025-01-18', '', '', 'AM,PM', 'AM,PM', '', 29, 0, '', '', NULL, NULL, NULL, 156, '2025-04-27', 'Sathaye College (Autonomous)', 'Past Event', '', '<p><span lang=\"EN-US\"><span style=\"color: #011a3a;\">On January 18, 2025, an Interdisciplinary workshop titled \"Approach to Manuscriptology and Paleontology\" was conducted in association with the AIC Department. The event took place at the AIC Department from 10:30 AM to 11:30 AM. The guest lecturer for this insightful session was Ms. Radha Sabnis, a renowned expert in the field. The workshop aimed to provide a comprehensive understanding of manuscriptology and paleontology, emphasizing their interconnection and significance in historical research...</span><o:p></o:p></span></p>', 'uploads/Events/IMG-20250119-WA0017.jpg', 'uploads/INTERDICIPLINARY-LECTURE-18-Jan.-25.pdf', '', '', '', '', 0, '2025-04-27', 1, ''),
(286, 'SOMAIYA COLLEGE COMPETITION (BHASHA SAPTAHA)', '', '', 'Inter-College', '2025-01-24', '2025-01-24', '', '', 'AM,PM', 'AM,PM', '', 29, 0, '', '', NULL, NULL, NULL, 156, '2025-04-27', 'K.J. Somaiya College', 'Past Event', '', '<p>The intercollegiate event, Bhasha Saptah, was a grand celebration of the timeless wisdom and literary brilliance of the Bhagavad-Gita. Organized with the objective of promoting Sanskrit literature and philosophical thought, the event was held from 9 AM to 5 PM and featured multiple competitions that encouraged participants to engage deeply with the teachings of the Bhagavad-Gita.</p>\r\n<p><strong><span style=\"color: #ba372a;\">Ellocution - 3rd Rank</span></strong></p>\r\n<p><strong><span style=\"color: #ba372a;\">Sanskrit Quiz - 3rd Rank</span></strong></p>\r\n<p><strong><span style=\"color: #ba372a;\">Sanskrit Story Writing - 2nd &amp; 3rd Rank</span></strong></p>', 'uploads/Events/IMG-20250124-WA0019.jpg', 'uploads/SOMAIYA-COMPITITION-24-Jan.-25.pdf', '', '', '', '', 0, '2025-04-27', 1, ''),
(287, 'GUEST LECTURES', '', '', 'Intra-College', '2024-07-28', '2025-04-30', '09:03', '11:02', '', '', 'M V Lokhande', 37, 0, '', '', NULL, NULL, NULL, 292, '2026-10-09', 'Department of Chemistry Room No 16', 'Past Event', '', '<p><strong>Seminars/Guest Lectures Conducted by Department:</strong></p>\r\n<ol>\r\n<li><a href=\"https://www.sathayecollege.edu.in/uploads/2--STAR-DBT-Guest-Lecture-on-Career-Guidance-26112024.pdf\">Guest Lecture on the Career Guidance</a></li>\r\n<li><a href=\"https://www.sathayecollege.edu.in/uploads/1--STAR-DBT-LAB-to-LAND-(-SAFETY-ASPECT)-Guest-lecture-KRUTI-HALANKAR.pdf\">Guest-lecture-KRUTI-HALANKAR-LAB-to-LAND-(-SAFETY-ASPECT)</a></li>\r\n<li><a href=\"https://www.sathayecollege.edu.in/uploads/1--STAR-DBT-LAB-to-LAND-(-SAFETY-ASPECT)-Guest-lecture-KRUTI-HALANKAR.pdf\">Community Engagement Activity</a></li>\r\n<li><a href=\"https://www.sathayecollege.edu.in/uploads/Online-Workshop-organised-in-7-February-2024.pdf\">Workshop on Laboratory Safety</a></li>\r\n<li><a href=\"https://www.sathayecollege.edu.in/uploads/Career-Guidance-lecture.pdf\">Career Guidance Lecture</a></li>\r\n</ol>', 'web-assets/img/event-placeholder.jpg', '', 'DBT Star College Scheme', 'UG and PG Students', 'null', '[{\"name\":\"Dr Kruti Halankar\"}]', 0, '2025-04-28', 1, ''),
(288, 'Legacy and Leadership Nurturing Success in Family Managed Business', '', '', '', '2023-08-04', '2023-08-04', '', '', 'AM,PM', 'AM,PM', '', 34, 0, '', '', NULL, NULL, NULL, 150, '2025-04-29', 'Auditorium', 'Past Event', '', '<p>Department of Commerce, Sathaye College (Autonomous) had organized a guest lecture on the topic \"Legacy and Leadership Nurturing Success in Family Managed Business\" at the ground floor auditorium. The resource person for the event was Mr. Krishna Rana, who is MD in Platinum Industries Pvt Ltd.</p>', 'uploads/Events/Legacy-and.jpg', 'uploads/Legacy-and-Leadership-Nurturing-Success-040823-(1).pdf', '', '', '', '', 0, '2025-04-29', 1, ''),
(289, 'Changing Landscape of career in Financial Market and Fintech Technology', '', '', '', '2023-07-13', '2023-07-13', '', '', 'AM,PM', 'AM,PM', '', 34, 0, '', '', NULL, NULL, NULL, 150, '2025-04-29', 'Auditorium', 'Past Event', '', '<p>Department of Commerce, Sathaye College (Autonomous) had organized a gues lecture on \"Changing Landscape of career in Financial Market and Fintech Technology\" on 13th July, 2023 at 10:30 am at ground floor auditorium. The resource person for the event were Mr. Ameen Khan and Mr. Sandeep Jadhav.&nbsp;</p>', 'uploads/Events/changing.jpg', 'uploads/Changing-Landscape-of-Career-130723.pdf', '', '', '', '', 0, '2025-04-29', 1, ''),
(290, 'Advanced Career Opportunities in Financial Market', '', '', '', '2023-08-24', '2023-08-24', '', '', 'AM,PM', 'AM,PM', '', 34, 0, '', '', NULL, NULL, NULL, 150, '2025-04-29', 'Auditorium', 'Past Event', '', '<p>Department of Commerce, Sathaye College (Autonomous) had organized a gues lecture on \"Advanced Career Opportunities in Financial Market\" on 24th August, 2023 at 10:30 am at ground floor auditorium. The resource person for the event were Mr. Vineet Gupta, Vice Presidenr( Business Development), Ticker Pvt. Ltd. and Nirmit founder of Nirmit Edusol Pvt. Ltd.&nbsp;</p>', 'uploads/Events/Nirmit.jpg', 'uploads/Advanced-Career-Opportunities-in-Financial-Market.pdf', '', '', '', '', 0, '2025-04-29', 1, ''),
