(368, '2020: Applications of Regression Analysis', '', '', 'Intra-College', '2021-03-12', '2021-03-12', '', '', 'AM,PM', 'AM,PM', '', 41, 0, '', '', NULL, NULL, NULL, 226, '2025-07-16', 'Online', 'Past Event', '', '<p>Applications of Regression Analysis</p>\r\n<p>Guest Speaker: Dr. Deepak Sakate</p>\r\n<p>The Department of Statistics organized a guest lecture on &ldquo;Applications of Regression Analysis&rdquo; on 12th March 2021. The speaker for the session was Dr. Deepak Sakate, Associate Professor at the Department of Statistics and Applied Mathematics, Central University of Tamil Nadu. The lecture was conducted online via Google Meet and commenced at 03:00 PM.</p>', 'uploads/Events/Regression-Image.png', 'uploads/Guest_Lecture_Report_Deepak_Sakate.pdf', '', '', '', '', 0, '2025-07-16', 1, ''),
(369, 'IdeaRush', '', '', 'Intra-College', '2025-07-14', '2025-07-14', '08:00', '11:00', '', '', 'Mr. Sagar Avsare', 43, 0, '', '', NULL, NULL, NULL, 326, '2025-12-22', 'IT Lab Room no 221', 'Past Event', '', '<p>The IT department organized a one-day event called \"Idea Rush\" on July 14,2025, where students were encouraged to come up with innovative solutions to real-life problems. The event aimed to foster creativity, critical thinking, and problem-solving skills among students.&nbsp;</p>', 'uploads/Events/20250714_95744amByGPSMapCamera.jpg', 'uploads/Report-IDEA-RUSH.pdf', NULL, 'SYBSc IT Students', '65', '[{}]', 0, '2025-07-30', 1, ''),
(370, 'Kalidas Din (कालिदासदिनम्) 25-26', '', '', 'Inter-College', '2025-07-23', '2025-07-23', '11:00', '', '', 'AM,PM', 'Dr. Swati Belsare, Ms. Prerana Mestry', 29, 0, '', '', NULL, NULL, NULL, 535, '2026-04-14', 'Ground Floor Auditorium, Sathaye College (Autonomous)', 'Past Event', '', '<p><span style=\"color: #ba372a;\"><strong>A Guest Lecture &amp; Prize Distribution on the Occasion of Kalidas Din</strong></span></p>\r\n<p style=\"text-align: justify;\"><span style=\"color: #230551;\">The Department of Sanskrit, Sathaye College (Autonomous), organized a guest lecture on Tuesday, 23rd July 2025 at 11.00 a.m. in the Ground Floor Auditorium of the college to celebrate Kalidas Din. The event began with a song on nature, reflecting Kalidas&rsquo; love for the monsoon and the natural world. The lecture on &ldquo;उपमा कालिदासस्य&rdquo; was delivered by Dr. Mrs. Mrunalini Newalkar-Gosavi, who shared valuable insights into Kalidas&rsquo; poetic brilliance. As part of the celebration, online intercollegiate competitions were conducted, and prize distribution took place during the event. We thank everyone who attended and made the program a success...</span></p>', 'uploads/Events/copy-1776165959-Copy-of-IMG_3546.JPG', 'uploads/1.-Kalidas-Din-25-26.pdf', NULL, NULL, '34', '[{\"name\":\"Dr. Mrs. Mrunalini Newalkar-Gosavi\"}]', 0, '2025-07-31', 1, ''),
