(591, 'Mega tree Planatation drive - 4th October 2025', 'Tree Plantation Drive on 4th October 2025\r\nOn 4th October 2025, Green Club and Green audit Committee and NSS Unit of Sathaye College&nbsp;(Autonomous) organized a Tree Plantation Drive in collaboration with the Inner Wheel Club of Mumbai Parleshwar and Ja', '2026', 'Intra-College', '2025-10-04', '2025-10-04', '09:30', '15:30', '', '', 'Dr. Deepali Mhapsekar', 0, 52, '', '', NULL, NULL, NULL, 337, '2026-04-30', 'Zilla Parishad, Post- Sakwar, Tahsil -Vasai, District- Palghar', 'Past Event', 'Past Event', '', 'uploads/Events/Tree-plantation-Drive--2.jpg', 'uploads/Tree-Plantation-Drive.docx', 'Inner Wheel Club of Mumbai Parleshwar and Janiv Charitable Trust', 'Students', '35', '[{}]', 1, '2026-04-27', 1, ''),
(592, 'RET Species Plantation Drive', 'RET species Plantation drive\r\nOn 2nd December 2025, the Green Club and Green audit Committee and NSS Unit of Sathaye College (Autonomous) successfully conducted Rare, Endangered and threatened species (RET) Plantation Drive in the college garden premises.', '2026', 'Intra-College', '2025-12-02', '2025-12-02', '12:00', '17:00', '', '', 'Dr. Deepali Mhapsekar', 0, 52, '', '', NULL, NULL, NULL, 337, '2026-04-30', 'Garden Area, Sathaye College (Autonomous)', 'Past Event', 'Past Event', '', 'uploads/Events/RET-species-Plantation-drive---3.jpg', 'uploads/Report-on-RET-species-Plantation-drive--2-Decemeber-2025.docx', NULL, 'Students', '9', '[{}]', 1, '2026-04-27', 1, ''),
(593, 'RET and fruit species Plantation Drive', 'RET and fruit species Plantation Drive\r\nGreen Club and Green Audit Committee and NSS Unit of Sathaye College (Autonomous) organized a RET and Fruit Species Plantation Drive on 17th January 2026 in the adivasi pada&rsquo;s of Palghar District. The primary ', '2026', 'Intra-College', '2026-01-17', '2026-01-19', '10:00', '17:00', '', '', 'Dr. Deepali Mhapsekar', 0, 52, '', '', NULL, NULL, NULL, 337, '2026-04-30', 'Sakwar, Bharol and Shisane Dhundalwadi and  Palghar Villages', 'Past Event', 'Past Event', '', 'uploads/Events/RET-AND-FRUIT-SPECIES-PLANTATION-DRIVE-AT-SAKWAR,BHAROL-AND-SHISANE-MALPADA-(17-01-26)-1.jpg', 'uploads/RET-AND-FRUIT-SPECIES-PLANTATION-DRIVE-AT-SAKWAR,BHAROL-AND-SHISANE-MALPADA-(17-01-26).docx', NULL, 'Students', '4', '[{}]', 1, '2026-04-27', 1, ''),
(594, 'RET and Fruit species Plantation Drive - 31st January and 1st February 2026', 'RET and Fruit species Plantation Drive &ndash; 31st January and 1st February 2026\r\nGreen Club and Green audit Committee and NSS Unit of Sathaye College (Autonomous) organized a RET and Fruit species Plantation Drive on 31st January 2026 and 1st February 2', '2026', 'Intra-College', '2026-01-31', '2026-02-01', '10:00', '17:00', '', '', 'Dr. Deepali Mhapsekar', 0, 52, '', '', NULL, NULL, NULL, 337, '2026-04-30', 'Shisane Dhundalwadi village and Devkhop Palghar Village', 'Past Event', 'Past Event', '', 'uploads/Events/31-st-January-and-1st-February-2026--RET-Plantation-1.jpg', 'uploads/31-st-January-and-1st-February-2026--RET-Plantation.docx', NULL, 'Students', '4', '[{}]', 1, '2026-04-28', 1, ''),
(595, 'Principal C. B. Joshi Memorial Lecture', 'Principal C. B. Joshi Memorial Lecture on 9th February 2026\r\nPrin. C. B. Joshi Memorial Lecture was successfully conducted at Sathaye College (Autonomous) in the presence of distinguished guests, faculty members, students and staff under Department of Geo', '2026', 'Intra-College', '2026-02-09', '2026-02-09', '11:30', '13:30', '', '', 'Dr. Deepali Mhapsekar', 0, 52, '', '', NULL, NULL, NULL, 337, '2026-04-30', 'Ground Floor Auditorium, Sathaye College (Autonomous)', 'Past Event', 'Past Event', '', 'uploads/Events/Principal-C.-B-Joshi-Mmeorial-lecture-on-9th-February-2026-1.jpg', 'uploads/Principal-C.-B-Joshi-Memorial-lecture-on-9th-February-2026.docx', NULL, 'Students', '70', '[{}]', 1, '2026-04-28', 1, ''),
