(309, 'Student\'s Activities', '2025-26', 1, '2026-04-24', 'uploads/IMG-20260417-WA0025.jpg~%~image', 0, 0, 264, '', '', 1, '27', '8', '', 575, 'Field Visit to Kolhapur', 1, ''),
(310, 'Ajanta Ellora Study Tour', '2025-26', 1, '2026-04-24', 'uploads/ajanta-ellora-5.jpeg~%~Ajanta Ellora Study Tour~^~uploads/ajanta-ellora-1.jpeg~%~Ajanta Ellora Study Tour~^~uploads/Ajanta-ell.jpeg~%~Ajanta Ellora Study Tour~^~uploads/ajanta-1.jpeg~%~Ajanta Ellora Study Tour~^~uploads/ajanta-2.jpeg~%~Ajanta Ellora Study Tour', 0, 0, 261, '', '', 1, '26', '', 'NULL', 0, 'The Department of Philosophy conducted a study tour to Ajanta Ellora from 9th to 11th January 2026 for the students of FYBA, SYBA and TYBA Philosophy students. The study tour was guided by Prof. Dr. Gautam Tenkale, Head Department of Philosophy and Dr. Sampada Chawan, Asst. Prof in Philosophy.', 1, ''),
(311, 'क्रांतिसूर्य महात्मा ज्योतिबा फुले निबंध स्पर्धा', '2025-26', 1, '2026-04-25', 'uploads/द्वितीय-क्रमांक.jpg~%~image~^~uploads/प्रथम-क्रमांक.jpg~%~image~^~uploads/तृतीय-क्रमांक.jpg~%~image~^~uploads/तृतीय-क्रमांक-(1).jpg~%~image~^~uploads/क्रांतिसूर्य-महात्मा-ज्योतिबा-फुले-निबंध-स्पर्धा.jpg~%~image', 0, 0, 275, '', '', 1, '59', '', '', 584, 'क्रांतिसूर्य महात्मा ज्योतिबा फुले निबंध स्पर्धा', 1, ''),
(312, 'Paper Bag Making Workshop', '2025-26', 1, '2026-04-25', 'uploads/Paper-bag-making-1.jpg~%~image~^~uploads/Paper-bag-making-2.jpg~%~image', 0, 0, 337, '', '', 1, '', '11', '52', 585, 'Paper Bag Making Workshop', 1, ''),
(313, 'Viksit Bharat Seminar', '2025-26', 1, '2026-04-25', 'uploads/IMG-20260420-WA0008.jpg~%~image~^~uploads/IMG-20260420-WA0009.jpg~%~image~^~uploads/IMG-20260420-WA0010.jpg~%~image~^~uploads/IMG-20260420-WA0036.jpg~%~image', 0, 0, 526, '', '', 1, '35', '6', '', 586, 'Sharp Institute of Individual and Organisational Development organised an informative seminar titled “Decode the Code on Wages, 2019” with the objective of creating awareness about recent labour reforms in India. The seminar aimed to provide a clear understanding of how the Code on Wages, 2019 impacts salary structure, minimum wages, payroll compliance, Provident Fund (PF), Employees’ State Insurance (ESIC), and bonus calculations. The session was highly beneficial for students, HR professionals, and business practitioners.', 0, ''),
(314, 'Flegling', '2025-26', 1, '2026-04-25', 'uploads/IMG-20260420-WA0079.jpg~%~image', 0, 0, 526, '', '', 1, '35', '6', '', 520, 'Winner for flegling- Aryan Kerkar', 0, ''),
(315, '5th INTRA INSTITUTIONAL RESEARCH CONCLAVE 2025-2026', '2025-26', 1, '2026-04-25', 'uploads/IMG-20260420-WA0039.jpg~%~image', 0, 0, 526, '', '', 1, '35', '6', '', 587, 'TYBMS students presented 6 papers for research and were published the same.', 0, ''),
(316, 'Fledgling 2026-2027', '2026-27', 1, '2026-04-25', 'uploads/IMG-20260420-WA0014.jpg~%~image~^~uploads/IMG-20260420-WA0015.jpg~%~image~^~uploads/IMG-20260420-WA0016.jpg~%~image~^~uploads/IMG-20260420-WA0017.jpg~%~image~^~uploads/IMG-20260420-WA0018.jpg~%~image', 0, 0, 526, '', '', 1, '35', '6', '', 520, 'Undergraduate & Postgraduate students had participated in the Research Poster Presentation under the Fledgling Resarchers Program.', 0, ''),
(317, 'International Conference on Business Management Practices & Integration of Technology.', '2025-26', 1, '2026-04-25', 'uploads/IMG-20260420-WA0040.jpg~%~image~^~uploads/IMG-20260420-WA0041.jpg~%~image~^~uploads/IMG-20260420-WA0042.jpg~%~image', 0, 0, 526, '', '', 1, '35', '6', '', 588, 'SYB.COM(MS) students from PTVA\'s Sathaye College (Autonomous) have achieved notable success at the International Conference on Business Management Practices & Integration of Technology held on 29th Nov, 2025.', 0, ''),
(318, 'Shodh Samiksha', '2026-27', 1, '2026-04-25', 'uploads/IMG-20260420-WA0020.jpg~%~image', 0, 0, 526, '', '', 1, '35', '6', '', 589, 'SYB.COM(MS) & TYBMS students presented research papers in the Thakur Ramnarayan College of Arts & Commerce. Wherein , 34 students students had participated in One day Multidisciplinary International Conference out of which 13 papers where successfully presented & published too.', 0, ''),
