(603, 4, 18, 0, 0, 0, 0, 0, '', '<div class=\"table-responsive\">\n<table class=\"table table-bordered\" style=\"width: 97.8226%; height: 129px;\">\n<tbody>\n<tr style=\"height: 18px;\">\n<th style=\"width: 19.9931%; height: 18px;\">Course</th>\n<th style=\"width: 86.5503%; height: 18px;\">Details and Syllabus&nbsp;</th>\n</tr>\n<tr style=\"height: 18px;\">\n<td style=\"width: 19.9931%; height: 18px;\">F.Y.Sem. 1</td>\n<td style=\"width: 86.5503%; height: 18px;\">[Will be updated soon as per NEP 2020]&nbsp;&nbsp;</td>\n</tr>\n<tr style=\"height: 54px;\">\n<td style=\"width: 19.9931%; height: 18px;\">F.Y.Sem. 2</td>\n<td style=\"width: 86.5503%; height: 18px;\">[Will be updated soon as per NEP 2020]&nbsp;&nbsp;</td>\n</tr>\n<tr style=\"height: 36px;\">\n<td style=\"width: 19.9931%; height: 21px;\">&nbsp;</td>\n<td style=\"width: 86.5503%; height: 21px;\">\n<div>Optional Papers I and II<br />Interaction of trade and religion</div>\n<div>&nbsp;</div>\n</td>\n</tr>\n<tr style=\"height: 18px;\">\n<td style=\"width: 19.9931%; height: 18px;\">S.Y.Sem.3</td>\n<td style=\"width: 86.5503%; height: 18px;\">Core Papers<br />Later Buddhist philosophy through Literature (Upto Yogacara)</td>\n</tr>\n<tr style=\"height: 18px;\">\n<td style=\"width: 19.9931%; height: 18px;\">&nbsp;</td>\n<td style=\"width: 86.5503%; height: 18px;\">Optional Papers I and II<br />Buddhism in South and Southeast Asia</td>\n</tr>\n<tr style=\"height: 18px;\">\n<td style=\"width: 19.9931%; height: 18px;\">S.Y.Sem.4</td>\n<td style=\"width: 86.5503%; height: 18px;\">Core Papers<br />Resurgence of Buddhism<br />Buddhist Art and Architecture</td>\n</tr>\n<tr style=\"height: 18px;\">\n<td style=\"width: 19.9931%; height: 18px;\">&nbsp;</td>\n<td style=\"width: 86.5503%; height: 18px;\">Optional Papers I and II<br />Buddhism in East Asian Culture</td>\n</tr>\n</tbody>\n</table>\n</div>', '1', 0, 1, '', 2, '2025-10-15', 0),
