(843, 4, 34, 0, 0, 0, 0, 0, '', '<div class=\"table-responsive\">\n<table class=\"table table-bordered\" style=\"width: 69.0284%; height: 618px;\">\n<tbody>\n<tr style=\"height: 18px;\">\n<th style=\"width: 20.2903%; height: 18px;\">Course</th>\n<th style=\"width: 86.2531%; height: 18px;\">Details and Syllabus&nbsp;</th>\n</tr>\n<tr style=\"height: 18px;\">\n<td style=\"height: 18px; width: 20.2903%;\" scope=\"row\">FYBCOM</td>\n<td style=\"height: 18px; width: 86.2531%;\">\n<p><span style=\"text-decoration: underline;\"><strong>SEMESTER- I</strong></span></p>\n<p><span style=\"text-decoration: underline;\"><strong>MAJOR COURSES:</strong></span></p>\n<ol>\n<li>Introduction to Business and Entrepreneurship&nbsp;</li>\n<li>Finance and Commerce I : Introduction to Business&nbsp;</li>\n</ol>\n<p><span style=\"text-decoration: underline;\"><strong>VOCATIONAL SKILL COURSE:</strong></span></p>\n<ol>\n<li>Business Registration&nbsp;</li>\n</ol>\n<p><span style=\"text-decoration: underline;\"><strong>SEMESTER- II</strong></span></p>\n<p><span style=\"text-decoration: underline;\"><strong>MAJOR COURSES:</strong></span></p>\n<ol>\n<li>Introduction to Service Sector&nbsp;</li>\n<li>Finance and Commerce II : Introduction to Service sector&nbsp;</li>\n</ol>\n<p><span style=\"text-decoration: underline;\"><strong>VOCATIONAL SKILL COURSE:</strong></span></p>\n<p><strong>&nbsp;</strong>&nbsp; &nbsp;1. Business Documents</p>\n<p><a title=\"FYBCOM SYLLABUS LINK\" href=\"https://drive.google.com/file/d/1icKhsrT8eo2Qxo1hbj2IGxfI49DZw4UU/view?usp=drive_link\">FYBCOM SYLLABUS LINK</a>&nbsp;</p>\n</td>\n</tr>\n<tr style=\"height: 180px;\">\n<td style=\"height: 180px; width: 20.2903%;\" scope=\"row\">SYBCOM</td>\n<td style=\"height: 180px; width: 86.2531%;\">\n<p><span style=\"text-decoration: underline;\"><strong>SEMETER- III&nbsp;</strong></span></p>\n<p><span style=\"text-decoration: underline;\"><strong>MAJOR COURSES:</strong></span></p>\n<div>1.Business Management&nbsp;</div>\n<p>2. Retail Management<br />3. Finance and Commerce III : Introduction to Management</p>\n<p>&nbsp;</p>\n<p><span style=\"text-decoration: underline;\"><strong>VOCATIONAL SKILL COURSE:</strong></span></p>\n<ol>\n<li>Tourism Management</li>\n</ol>\n<p>&nbsp;</p>\n<p><span style=\"text-decoration: underline;\"><strong>SEMETER- IV</strong></span></p>\n<p><span style=\"text-decoration: underline;\"><strong>MAJOR COURSES:</strong></span></p>\n<p>1. Production Management and Financial Market</p>\n<p>2. Finance and Commerce IV: Introduction Production Management and Financial Market</p>\n<p>3. Introdcution to banking System<br /><br /></p>\n<p><a title=\"SYBCOM SYLLABUS LINK\" href=\"https://drive.google.com/file/d/1aueNfbXGTlHkg5QJ09jt_NYQFyKx7duY/view?usp=drive_link\">SYBCOM SYLLABUS LINK</a></p>\n</td>\n</tr>\n<tr style=\"height: 180px;\">\n<td style=\"height: 276px; width: 20.2903%;\" scope=\"row\">TYBCOM</td>\n<td style=\"height: 276px; width: 86.2531%;\">\n<p><span style=\"text-decoration: underline;\"><strong>SEMETER- V</strong></span></p>\n<p><span style=\"text-decoration: underline;\"><strong>MAJOR COURSES:</strong></span></p>\n<ol>\n<li>Marketing</li>\n<li>Advertising-I</li>\n<li>Finance and Commerce V</li>\n<li>IKS : Trade and Commerce in Ancient India</li>\n</ol>\n<p><span style=\"text-decoration: underline;\"><strong>VOCATIONAL SKILL COURSE</strong></span></p>\n<ol>\n<li>E-Commerce</li>\n</ol>\n<p><span style=\"text-decoration: underline;\"><strong>SEMSETER-VI</strong></span></p>\n<ol>\n<li>Human Resource Management&nbsp;</li>\n<li>Advertising-II</li>\n<li>Finance and Commerce VI</li>\n</ol>\n<p><a title=\"TYBCOM SYLLABUS LINK\" href=\"https://drive.google.com/file/d/1VALMDNH-aNLgoQjP8k30k8YkMDESqs7L/view?usp=drive_link\">TYBCOM SYLLABUS LINK</a></p>\n</td>\n</tr>\n</tbody>\n</table>\n</div>', '1', 0, 1, '', 283, '2026-04-20', 0),
(844, 5, 34, 0, 0, 0, 0, 0, '', '<p><a href=\"https://drive.google.com/file/d/1dKVu192ltTAxj6ZXaGkpTYW-QSOC5ChG/view?usp=sharing\">Syllabus for T.Y.B.Com (Commerce)</a></p>\n<p><a href=\"https://sathayecollege.edu.in/uploads/SYBCOM-SYLLABUS-FOR-24-25-(1).pdf\">Syllabus for S.Y.B.Com (Commerce)</a></p>\n<p><a href=\"https://sathayecollege.edu.in/uploads/copy-1745900396-F.Y.B.Com-Syllabus.pdf\">Syllabus for F.Y.B.Com</a> ( Commerce)</p>', '1', 0, 1, '', 283, '2026-04-18', 0),
