(918, 4, 39, 0, 0, 0, 0, 0, '', '<table class=\"table table-bordered\" style=\"width: 73.9526%; height: 47px;\">\n<tbody>\n<tr style=\"height: 57px;\">\n<th style=\"width: 100%; height: 10px; text-align: left;\" scope=\"row\">Courses Available</th>\n</tr>\n<tr style=\"height: 37px;\">\n<td style=\"width: 100%; height: 37px;\" scope=\"row\">\n<p>B.Sc. Microbiology - <a href=\"https://drive.google.com/file/d/1aflpnoAJMf1jzOcb-nBydbjEplubdzuH/view?usp=sharing\" target=\"_blank\" rel=\"noopener\">Link for Brochure</a></p>\n</td>\n</tr>\n<tr>\n<td style=\"width: 100%;\" scope=\"row\">\n<p>B.Sc. Microbiology with Honors - Link for Brochure</p>\n</td>\n</tr>\n<tr style=\"height: 37px;\">\n<td style=\"width: 100%; height: 37px;\" scope=\"row\">MSc Microbiology - <a href=\"https://drive.google.com/file/d/1R9-5LP_GL4iW11gfeSf6IFYg4BDs1uCs/view?usp=sharing\" target=\"_blank\" rel=\"noopener\">Link for Brochure</a></td>\n</tr>\n<tr style=\"height: 37px;\">\n<td style=\"width: 100%; height: 37px;\" scope=\"row\">Link : <a href=\"https://drive.google.com/file/d/1n6K2PdX8PgYuIoZQmkd5mbCkcju52UGj/view?usp=sharing\" target=\"_blank\" rel=\"noopener\">Course Structure for UG and PG in Microbiology</a></td>\n</tr>\n</tbody>\n</table>', '1', 0, 1, '', 305, '2026-04-30', 0),
(919, 5, 39, 0, 0, 0, 0, 0, '', '<p><span style=\"font-family: \'times new roman\', times, serif;\"><strong>NEP 1.1 syllabi (wef 2024-25)</strong></span></p>\n<ul>\n<li><a href=\"https://sathayecollege.edu.in/uploads/MICROBIOLOGY-NEP-1.1-revised-Structure-for-AY-2026-27.docx.pdf\" target=\"_blank\" rel=\"noopener\"><span style=\"font-family: \'times new roman\', times, serif;\">Microbiology NEP 1.1 Structure 2024</span></a></li>\n<li><span style=\"font-family: \'times new roman\', times, serif;\"><a href=\"https://sathayecollege.edu.in/uploads/FYBSC-Microbiology-Major-Syllabus-NEP-1.0-2024-25.pdf\" target=\"_blank\" rel=\"noopener\">F. Y. B. Sc. Microbiology&nbsp; As Per NEP 1.1-Major 2024</a></span></li>\n<li><span style=\"font-family: \'times new roman\', times, serif;\"><a href=\"https://sathayecollege.edu.in/uploads/FY-Microbiology-Open-Elective-Syllabus-NEP-1.0-2024-25.pdf\" target=\"_blank\" rel=\"noopener\">F. Y. B. Sc. / B.A. Microbiology As Per NEP 1.1-Open Electives 2024</a></span></li>\n<li><a href=\"https://sathayecollege.edu.in/uploads/SYBSc-Microbiology-NEP-1.1-Syllabus-2025-26.pdf\" target=\"_blank\" rel=\"noopener\"><span style=\"font-family: \'times new roman\', times, serif;\">S.Y.B.Sc. Microbiology NEP 1.1 Syllabus Major, Minor,VSC 2025-26</span></a></li>\n<li><span style=\"font-family: \'times new roman\', times, serif;\"><a href=\"https://sathayecollege.edu.in/uploads/TYBSc-Microbiology-Major,-Elective,-VSC-Syllabus-under-NEP-1.1-(2026-27).pdf\" target=\"_blank\" rel=\"noopener\">TYBSc Microbiology Major, Elective, VSC Syllabus under NEP 1.1 (2026-27)</a></span></li>\n</ul>\n<p><span style=\"font-family: \'times new roman\', times, serif;\"><strong>NEP 0.0 syllabi (wef 2023-24)</strong></span></p>\n<ul>\n<li><span style=\"font-family: \'times new roman\', times, serif;\"><a href=\"https://sathayecollege.edu.in/uploads/NEP-Course-Structure-Science-Stream-0.0-FY-structure-2023-updated-18th-Nove-24.pdf\" target=\"_blank\" rel=\"noopener\">Microbiology NEP 0.0 Structure 2023</a></span></li>\n<li><span style=\"font-family: \'times new roman\', times, serif;\"><a href=\"https://sathayecollege.edu.in/uploads/FYBSC-Microbiology-Syllabus-NEP-0.0-year-2023.pdf\" target=\"_blank\" rel=\"noopener\">F.Y.B.Sc Microbiology Syllabus NEP 0.0 Major, Minor, VSC, OE 2023</a></span></li>\n<li><span style=\"font-family: \'times new roman\', times, serif;\"><a href=\"https://sathayecollege.edu.in/uploads/SYBSC-Major-Syllabus-NEP-2024-25.pdf\" target=\"_blank\" rel=\"noopener\">S. Y. B.Sc. Microbiology Syllabus NEP 0.0 -Major 2023</a></span></li>\n<li><span style=\"font-family: \'times new roman\', times, serif;\"><a href=\"https://sathayecollege.edu.in/uploads/SYBSC-Minor-Syllabus-NEP-2024-25.pdf\" target=\"_blank\" rel=\"noopener\">S. Y. B.Sc. Microbiology Syllabus NEP 0.0-Minor 2023</a></span></li>\n<li><span style=\"font-family: \'times new roman\', times, serif;\"><a href=\"https://sathayecollege.edu.in/uploads/SYBSC-VSC-Syllabus-NEP-2024-25.pdf\" target=\"_blank\" rel=\"noopener\">S. Y. B.Sc. Microbiology&nbsp; Syllabus NEP 0.0 -Vocational Skill Course 2023</a></span></li>\n<li><a href=\"https://sathayecollege.edu.in/uploads/TYBSC-Microbiology-Syllabus-NEP-0.0-Major,-Minor,IKS,VSC.pdf\" target=\"_blank\" rel=\"noopener\"><span style=\"font-family: \'times new roman\', times, serif;\">T.Y.B.Sc. Microbiology Syllabus NEP 0.0- Major, Minor,IKS, VSC 2025</span></a></li>\n</ul>\n<p><span style=\"font-family: \'times new roman\', times, serif;\"><strong>Autonomous Syllabus</strong></span></p>\n<ul class=\"list-items-pdf\">\n<li style=\"text-align: justify;\"><span style=\"font-family: \'times new roman\', times, serif;\"><a href=\"https://sathayecollege.edu.in/uploads/FYBSc-Syllabus-Microbiology-2022-23-Autonomy.pdf\" target=\"_blank\" rel=\"noopener\">F. Y. B.Sc. Microbiology under Autonomy 2022-23</a></span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: \'times new roman\', times, serif;\"><a href=\"https://sathayecollege.edu.in/uploads/copy-1731126219-SYBSC-Microbiology-Syllabus-2023-Autonomy.pdf\" target=\"_blank\" rel=\"noopener\">S. Y. B.Sc. Microbiology under Autonomy 2023-24</a></span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: \'times new roman\', times, serif;\"><a href=\"https://sathayecollege.edu.in/uploads/TYBSC-Syllabus-Autonomous-2024--25.pdf\" target=\"_blank\" rel=\"noopener\">T. Y. B.Sc. Microbiology under Autonomy 2024-25</a></span></li>\n</ul>\n<p style=\"text-align: justify;\"><span style=\"font-family: \'times new roman\', times, serif;\"><strong>University syllabus</strong></span></p>\n<ul>\n<li><span style=\"font-family: \'times new roman\', times, serif;\"><a href=\"https://sathayecollege.edu.in/uploads/4.15-F.Y.B.Sc-Microbiology.pdf\" target=\"_blank\" rel=\"noopener\">4.15-F.Y.B.Sc-Microbiology</a></span></li>\n<li><span style=\"font-family: \'times new roman\', times, serif;\"><a href=\"https://sathayecollege.edu.in/uploads/4.217-S.Y.B.Sc-Microbiology.pdf\" target=\"_blank\" rel=\"noopener\">4.217-S.Y.B.Sc-Microbiology</a></span></li>\n<li><span style=\"font-family: \'times new roman\', times, serif;\"><a href=\"https://sathayecollege.edu.in/uploads/4.51-T.Y.B.Sc-Microbiology.pdf\" target=\"_blank\" rel=\"noopener\">4.51-T.Y.B.Sc-Microbiology</a></span></li>\n<li><span style=\"font-family: \'times new roman\', times, serif;\"><a href=\"https://sathayecollege.edu.in/uploads/4.9-Applied-Component-in-Microbiology-Food-Production-and-Processing.pdf\" target=\"_blank\" rel=\"noopener\">4.9-Applied Component in Microbiology &nbsp;Food Production and Processing</a></span></li>\n</ul>\n<p><span style=\"font-family: \'times new roman\', times, serif;\"><strong>Postgraduate program: MSc Microbiology Syllabus</strong></span></p>\n<ul class=\"list-items-pdf\">\n<li><span style=\"font-family: \'times new roman\', times, serif;\"><a href=\"https://sathayecollege.edu.in/uploads/MSC-PART-I-Microbiology-Syllabus-AC-JAN24-4.2-2024-25.pdf\" target=\"_blank\" rel=\"noopener\">M.Sc Part I Microbiology Syllabus&nbsp; NEP 1.1 2024-2025</a></span></li>\n<li><a href=\"https://sathayecollege.edu.in/uploads/MSc-Part-2-Microbiology-Syllabus-2025-2026-NEP-1.1-(1).pdf\" target=\"_blank\" rel=\"noopener\"><span style=\"font-family: \'times new roman\', times, serif;\">M. Sc. Part II Microbiology Syllabus NEP 1.1 2025-2026</span></a></li>\n</ul>\n<p><span style=\"font-family: \'times new roman\', times, serif;\"><strong>Add-On Course</strong></span></p>\n<p><span style=\"font-family: \'times new roman\', times, serif;\"><a href=\"https://sathayecollege.edu.in/uploads/Food-Nutrition-and-Dietetics---Add-On-Course-Dept-of-Microbiology.pdf\" target=\"_blank\" rel=\"noopener\">FOOD NUTRITION &amp; DIETETICS Syllabus</a></span></p>', '1', 0, 1, '', 305, '2026-04-15', 0),
