(978, 4, 43, 0, 0, 0, 0, 0, '', '<p><strong>FYBSc IT</strong></p>\n<p><strong>Semester I</strong></p>\n<ul>\n<li><strong>Major</strong>: Imperative Programming, Database Management System</li>\n<li><strong>Minor</strong>: Digital Electronics&nbsp;</li>\n<li><strong>Vocational Skill Cours</strong>e: Computer Lab Technician</li>\n<li><strong>Open Elective</strong>: Introduction to Computing Concepts, E- Commerce</li>\n</ul>\n<p><strong>Semester II</strong></p>\n<ul>\n<li><strong>Major</strong>: Web Programming, Operating Systems&nbsp;</li>\n<li><strong>Minor</strong>: Discrete Mathematics&nbsp;</li>\n<li><strong>Vocational Skill Course</strong>: Website Development using WordPress&nbsp;</li>\n<li><strong>Open Elective</strong>: Eco-Friendly IT, Cyber Security</li>\n</ul>\n<p><strong>SYBSc IT</strong></p>\n<p><strong>Semester III</strong></p>\n<ul>\n<li><strong>Major</strong>: Python Programming, Data Structures I, Computer Networks Practical</li>\n<li><strong>Minor</strong>: Matrices and Ordinary Differential Equations, Electronics and Telecommunication</li>\n<li><strong>Vocational Skill Course</strong>: Handling real time data using Apache Kafka</li>\n<li><strong>Open Elective</strong>: Data Manipulation using Python</li>\n</ul>\n<p><strong>Semester IV</strong></p>\n<ul>\n<li><strong>Major</strong>: Core Java, Data Structures II, Software Engineering</li>\n<li><strong>Minor</strong>: Descriptive Statistics, Embedded Systems</li>\n<li><strong>Open Elective</strong>: Website Development using Wordpress</li>\n</ul>\n<p><strong>TYBSc IT</strong></p>\n<p><strong>Semester V</strong></p>\n<ul>\n<li><strong>Major</strong>: Software Project Management, Full Stack Web Programming, Artificial Intelligence, Indian Knowledge System &ndash; IT</li>\n<li><strong>Major Elective</strong>: Enterprise Java, Linux Administration</li>\n<li><strong>Minor</strong>: Computer Oriented Statistical Techniques, Internet of Things I</li>\n<li><strong>Vocational Skill Course</strong>: Building Scalable and Efficient Systems</li>\n</ul>\n<p><strong>Semester VI</strong></p>\n<ul>\n<li><strong>Major</strong>: Software Testing and Quality Assurance, Security In Computing, Business Intelligence, Configuration Management</li>\n<li><strong>Major Elective</strong>: Principles of Geographic Information System, Next Generation Technology,</li>\n<li><strong>Minor</strong>: Mathematical Techniques for Analysis and Inference, Internet of Things II</li>\n</ul>\n<p><strong>MSc Data Science Part I</strong></p>\n<p><strong>Semester I</strong></p>\n<ul>\n<li><strong>Major</strong>: Data Science Foundation: Data Structures and Analysis of Algorithms, Data Management for Data Science, Mathematical and Statistical Foundation for Data Science</li>\n<li><strong>Major Elective</strong>: Soft Computing Techniques, Cloud Computing</li>\n<li>Research Methodology</li>\n</ul>\n<p><strong>Semester II</strong></p>\n<ul>\n<li><strong>Major</strong>: Big Data Analytics, Data Visualization, Tools for Data Science: Python and R Practical</li>\n<li><strong>Major Elective</strong>: Time Series Analysis, Bioinformatics with BioPython</li>\n</ul>\n<p><strong>MSc Data Science Part II</strong></p>\n<p><strong>Semester III</strong></p>\n<ul>\n<li><strong>Major</strong>: Data Engineering, Machine Learning, Applied Data Science</li>\n<li><strong>Major Eelective</strong>: Advanced Analytics, Spatial Data Analysis</li>\n</ul>\n<p><strong>Semester IV</strong></p>\n<ul>\n<li><strong>Major</strong>: Natural Language Processing, Deep Learning</li>\n<li><strong>Major Elective</strong>: Generative AI, SAS Programming for Analytics</li>\n</ul>\n<p>&nbsp;</p>', '1', 0, 1, '', 2, '2025-10-15', 0),
(979, 5, 43, 0, 0, 0, 0, 0, '', '<p>FYBSc IT</p>\n<ul>\n<li><a href=\"https://www.sathayecollege.edu.in/uploads/copy-1745642435-FYBSc-IT--2023-24-(NEP-2020).pdf\">Syllabus Of FYBSc IT- 2023-24 (NEP 2020)</a></li>\n</ul>\n<p>SYBSc IT</p>\n<ul>\n<li><a href=\"https://www.sathayecollege.edu.in/uploads/SYBSc-IT---2024-25-(NEP-2020).pdf\">Syllabus Of SYBScIT - 2024-25 (NEP 2020)</a></li>\n<li><a href=\"https://www.sathayecollege.edu.in/uploads/SYBSc-IT---2023-24.pdf\">Syllabus Of SYBScIT - 2023-24</a></li>\n</ul>\n<p>TYBSc IT</p>\n<ul>\n<li><a href=\"https://www.sathayecollege.edu.in/uploads/TYBScIT-Syllabus-NEP-2020--2025-26-Department-of-IT.pdf\">Syllabus Of TYBScIT - 2025-26 (NEP 2020)</a></li>\n<li><a href=\"https://www.sathayecollege.edu.in/uploads/TYBSc-IT---2024-25.pdf\">Syllabus Of TYBScIT - 2024-25</a></li>\n</ul>\n<p>MSc Data Science</p>\n<ul>\n<li><a href=\"https://www.sathayecollege.edu.in/uploads/MSc-Data-Science---Part-II---2024-25-(NEP-2020).pdf\">Syllabus Of MSc Data Science - Part II - 2024-25 (NEP 2020)</a></li>\n<li><a href=\"https://www.sathayecollege.edu.in/uploads/MSc-Data-Science---Part-I---2023-24-(NEP-2020).pdf\">Syllabus Of MSc Data Science - Part I - 2023-24 (NEP 2020)</a></li>\n<li><a href=\"https://www.sathayecollege.edu.in/uploads/MSc-Data-Science---Part-II---2023-24.pdf\">Syllabus Of MSc Data Science - Part II - 2023-24</a></li>\n<li><a href=\"https://www.sathayecollege.edu.in/uploads/MSc-Data-Science---Part-I---2022-23.pdf\">Syllabus Of MSc Data Science - Part I - 2022-23</a></li>\n</ul>\n<p>MSc IT</p>\n<ul>\n<li><a href=\"https://www.sathayecollege.edu.in/uploads/MSc-IT---Part-II---2024-25-(NEP-2020).pdf\">Syllabus Of MSc IT - Part II - 2024-25 (NEP 2020)</a></li>\n<li><a href=\"https://www.sathayecollege.edu.in/uploads/MScIT---Part-II---2023-24.pdf\">Syllabus Of MScIT - Part II - 2023-24</a></li>\n<li><a href=\"https://www.sathayecollege.edu.in/uploads/MSc-IT---Part-I---2023-24-(NEP-2020).pdf\">Syllabus Of MSc IT - Part I - 2023-24 (NEP 2020)</a></li>\n<li><a href=\"https://www.sathayecollege.edu.in/uploads/MSc-IT---Part-I---2022-23.pdf\">Syllabus Of MSc IT - Part I - 2022-23</a></li>\n</ul>', '1', 0, 1, '', 326, '2026-08-11', 0),
