(1247, 59, 49, 0, 0, 0, 0, 0, '', '<div class=\"row\">\n<div class=\"col-sm-6 col-md-4\">\n<article class=\"post clearfix mb-30 bg-lighter\">\n<div class=\"entry-header\">\n<div class=\"post-thumb thumb\">2021-22</div>\n<div class=\"post-thumb thumb\">&nbsp;</div>\n<div class=\"post-thumb thumb\">&nbsp;</div>\n<div class=\"post-thumb thumb\">2022-23</div>\n<div class=\"post-thumb thumb\">2023-24</div>\n<div class=\"post-thumb thumb\">&nbsp;</div>\n<div class=\"post-thumb thumb\"><strong style=\"text-align: center;\">2024-25</strong></div>\n</div>\n</article>\n</div>\n</div>\n<div class=\"post-thumb thumb\"><strong>2025-26</strong></div>', '1', 0, 1, '', 333, '2026-02-22', 0),
(1248, 127, 49, 0, 0, 0, 0, 0, '', '<p class=\"text-break\"><span style=\"color: #000000;\"><strong><a href=\"https://www.instagram.com/plantae_2023/\">Instagram&nbsp;</a></strong></span></p>\n<p class=\"text-break\"><b>&nbsp;<a href=\"https://www.instagram.com/plantae_2023/\" title=\"Plantae \">https://www.instagram.com/plantae_2023/</a></b></p>\n<p><b>Facebook</b></p>\n<p class=\"text-break\"><b><a href=\"https://www.facebook.com/share/g/tvReK3igfvHT9Bq4/\">https://www.facebook.com/share/g/tvReK3igfvHT9Bq4/</a></b></p>', '1', 0, 1, '', 451, '2025-09-23', 0),
