INSERT INTO `tbl_section_info` (`dsi_id`, `dsi_dsm_id`, `dsi_dsl_id`, `dsi_asl_id`, `dsi_ayl_id`, `dsi_assl_id`, `dsi_lib_id`, `dsi_res_id`, `dsi_new_content`, `dsi_content`, `dsi_is_display_on_website`, `dsm_order`, `approve_bit`, `rejected_reason`, `dsi_user_id`, `dsi_time`, `delete_bit`) VALUES
(2539, 77, 276, 0, 0, 0, 0, 0, '', '<ol>\n<li><strong>Resource Person</strong> in a workshop organized for Faculties by CKT College (Panvel) in association with University of Mumbai on &ldquo;Revised Syllabus for T.Y.B.Com (BAF-Sem-V &amp; VI) &ldquo;in the subject &ldquo;Cost Accounting, Management Control&rdquo; on 10<sup>th</sup> May 2018.</li>\n<li><strong>Resource Person</strong> in a workshop organized for Faculties by CKT College (Panvel) in association with University of Mumbai on &ldquo;Revised Syllabus for T.Y.B.Com (FAA-Sem-V &amp; VI) &ldquo;in the subject &ldquo;Cost Accounting&rdquo; on 10<sup>th</sup> May 2018.</li>\n<li><strong>Resource Person</strong> in a workshop organized for Faculties by Mahatma Night Degree College (Chembur) in association with University of Mumbai on &ldquo;Revised Syllabus for T.Y.B.Com (Sem-VI) &ldquo;in the subject &ldquo;Cost Accounting&rdquo; on 7-7-2018.</li>\n<li><strong>Resource Person</strong> in a workshop organized for Faculties by Valia College (Andheri) in association with University of Mumbai on &ldquo;Revised Syllabus in Indirect taxes-GST for&nbsp; Y.B.Com (Sem-VI) &ldquo; on 4-10-2018</li>\n<li><strong>Chief Guest and Resource Person</strong> in a workshop organized for Faculties by SIES (Nerul) College in association with University of Mumbai on &ldquo;Syllabus Revision on Indirect taxation of T.Y.B.Com&rdquo; 27-10-2018.</li>\n<li><strong>Chief Guest and Resource Person</strong> in a workshop organized for Faculties by S.H.M College (Ulhasnagar) in association with University of Mumbai on &ldquo;Revised Syllabus for T.Y.B.Com (Sem-VI) Indirect taxes&rdquo; on 8-12-2018</li>\n<li><strong>Resource Person</strong> in a workshop organized for Faculties by KES&rsquo;s B.K.Shroff College (Kandivali) in association with University of Mumbai on &ldquo;Revised Syllabus in Indirect taxes (GST Act) for T.Y.B.Com (Sem-VI) &ldquo;on 7-2-2019.</li>\n<li><strong>Resource Person</strong> in a workshop for Faculties by Chandrabhan Sharma College (Powai) in association with University of Mumbai on &ldquo; GST- Syllabus, examination, Assessment, Evaluation and Re-evaluation wrt B.Com,M.Com and Self-financing courses on 9-2-2019</li>\n<li><strong>Resource Person </strong>in a workshop organized for students &amp; Faculties by B.N.N.College (Bhiwandi) on &ldquo;Goods &amp; Service Tax&rdquo; for the students of B.Com,M.Com, BAF, BMS, BFM on 25-2-2019</li>\n<li><strong>Resource Person</strong> in a workshop organized for students &amp; Faculties by Thakur College (Kandivali) in association with University of Mumbai on &ldquo;Goods &amp; Service Tax&rdquo; for the students of B.Com,M.Com, BAF, BMS, BFM on 2-3-2019</li>\n<li><strong> </strong><strong>Guidance Lecture</strong> to the students of M.Com-I and M.Com-II of the University of Mumbai, organized by Department of Commerce of the University of Mumbai on &ldquo;Overview of Goods &amp; Service Tax&rdquo; on 18-3-2019.</li>\n<li><strong> </strong><strong>Resource Person</strong> in an Online Lecture on &lsquo;Process Costing&rdquo; forG &amp; P.G. Students organized by Indian Accounting Association on 23-5-2020.</li>\n<li><strong> </strong><strong>Resource Person</strong> in an Online Lecture on &lsquo;Cost Accounting &ndash; Basics of Cost Accounting &amp; Cost Classifications&rdquo; for U.G &amp; P.G. Students organized by Indian Accounting Association &amp; K.G.Mittal College (Malad) on 8-5-2020.</li>\n<li>Coordinator for Workshop on &ldquo;Introduction to MOOC&rsquo;s and SWAYAM&rdquo; IN Sathaye College on 9-12-2019</li>\n<li><strong>Resource Person</strong> in a workshop on &lsquo;Revised Syllabus &amp; Question paper pattern of B.Com(Accountancy) &amp; BAF (Indirect Taxes) organized by Chandrabhan Sharma College (Powai) in association with University of Mumbai on 20-8-2019.</li>\n<li><strong> </strong><strong>Resource Person</strong> for Expert Guidance on Cost Accounting (TYBCOM) organized by DTSS College (Malad) on 25-2-2020.</li>\n<li><strong> </strong><strong>Resource Person</strong> in an Online Lecture on &lsquo;Marginal Costing &ldquo; U.G &amp; P.G. Students organized by Indian Accounting Association, Thane Branch on 13-6-2020.</li>\n<li>Resource Person in Workshop for Subject Teachers for Orienting towards NEP 2020 at Dr.V.N.Bedekar Institute of Managemnet Studies organised by University of Mumbai on 27th Sept 24</li>\n<li>Resource Person in Workshop for Subject Teachers for Orienting towards NEP 2020 at M.L.Dahanukar College organised by University of Mumbai on 28th Sept 24</li>\n</ol>', '1', 0, 1, '', 276, '2025-09-23', 0),
