INSERT INTO `tbl_section_info` (`dsi_id`, `dsi_dsm_id`, `dsi_dsl_id`, `dsi_asl_id`, `dsi_ayl_id`, `dsi_assl_id`, `dsi_lib_id`, `dsi_res_id`, `dsi_new_content`, `dsi_content`, `dsi_is_display_on_website`, `dsm_order`, `approve_bit`, `rejected_reason`, `dsi_user_id`, `dsi_time`, `delete_bit`) VALUES
(2839, 78, 299, 0, 0, 0, 0, 0, '', '<ol>\n<li>Presented paper in two days International Conference on \"Thermodynamic studies of interactions of DABCO based ionic liquids\" organised by P. D. V. P. college on \"Multidisciplinary approach in basic and applied sciences\" in&nbsp; Feb. 2023.&nbsp;</li>\n<li>Attended one day International E-conference on &ldquo;Advanced functional Nanomaterial&rsquo;s and their device Applications&rdquo; organised by Krishna Mahavidhyalaya, Rethare BK, Karad, Satara on 10<sup>th</sup><span>&nbsp;</span>August 2020.</li>\n<li><strong><span></span></strong>Attended one day International E-conference on &ldquo; Modern Instrumental and Characterisation Techniques in Applied Sciences&rdquo; organised by Uttarakhand Science Education and Research Centre, MIET Kumaon Haldwani, Uttarakhand from 5<sup>th</sup><span>&nbsp;</span>July to 6<sup>th</sup><span>&nbsp;</span>July 2020.</li>\n<li><strong><span></span></strong>Poster Presented on &ldquo;Spectroscopic Studies of Self Aggregation of Methylene blue in aqueous solutions of Diethyl ammonium based ionic liquids&rdquo; in National Conference on &ldquo; Emerging trends in Chemical and material Sciences&rdquo; Organised by Department of Chemistry, Shivaji University, Kolhapur from 6<sup>th</sup><span>&nbsp;</span>to 7<sup>th</sup><span>&nbsp;</span>March 2020.</li>\n<li><strong><span></span></strong>One day State level conference on &ldquo; Intellectual Property Rights&rdquo; organised by PTVA&rsquo;s Sathaye college, Vile Parle (East), Mumbai on 20<sup>th</sup><span>&nbsp;</span>January 2020.</li>\n<li><strong><span></span></strong>Dielectric relaxation study of Diethylammonium based protic ionic liquids and their aqueous solutions using Time Domain Reflectometry Technique in the Frequency range of 10 MHz to 50MHz, shrikant P. Musale, Sandeep P. Shinde, Dilip H. Dagade in National conference organised by Department of Chemistry, Shivaji University, Kolhapur entiled &ldquo;Recent trends in Chemistry and Material Science&rdquo; on 9<sup>th</sup>2019.</li>\n<li><strong><span></span></strong>Volumetric studies of interactions of polyethylene glycols and amino Acid ionic liquids in aqueous solutions at 298.15 K,<span>&nbsp;</span><strong>Sandeep P. Shinde</strong>, D. H. Dagade, 9<sup>th</sup><span>&nbsp;</span>national conference on TCBEP-2014, organised by<span>&nbsp;</span><strong>Indian Thermodynamic Society</strong><span>&nbsp;</span>in Department of Chemistry, Sardar Patel University, Vallabh Vidyanagar, Gujarat. On 17<sup>th</sup><span>&nbsp;</span>-18<sup>th</sup><span>&nbsp;</span>2014<span>&nbsp;</span><strong>(Poster)</strong></li>\n<li><strong><span></span></strong>Thermodynamic studies of ionic interactions in aqueous solutions of 1-butyl-3-methylimidazolium Alanine ionic liquids. D. H. Dagade,<span>&nbsp;</span><strong>P. Shinde</strong>, K. R. Madkar, S. S. Barage, 7<sup>th</sup><span>&nbsp;</span>national conference on TCBEP-2012, organised by<span>&nbsp;</span><strong>Indian Thermodynamic Society</strong><span>&nbsp;</span>in Department of Chemistry, Sri Venkateswara University, Tirupati. On 10<sup>th</sup><span>&nbsp;</span>-12<sup>th</sup><span>&nbsp;</span>Dec 2012.<span>&nbsp;</span><strong>(Best poster presentation Award)</strong></li>\n<li><strong><span></span></strong><span>Studies of volumetric and compressibility properties of amino acid ionic liquids in aqueous solutions&rdquo; in&nbsp;</span><strong>1<sup>st</sup><span>&nbsp;</span>&ldquo;CRSI ZONAL MEETING&rdquo; held in NCL Pune</strong><span>&nbsp;</span>and organised by Chemical Research Society India. 2010<span>&nbsp;</span><strong>(Poster)</strong></li>\n<li><strong></strong>Molar volumes of transfer of AAILs from water to aqueous solutions containing ~0.2 mol.kg<sup>-1</sup><span>&nbsp;</span>of PEG 400, 600,1000 at 298.15 K.<strong>, S. P. Shinde</strong><span>&nbsp;</span>and D, H, Dagade, National Conference organized by<span>&nbsp;</span><strong>Rajarshi Chatrapati Shahu College, Kolhapur</strong><span>&nbsp;</span>on 20<sup>th</sup><span>&nbsp;</span>to 21<sup>st</sup><span>&nbsp;</span>2013.<span>&nbsp;</span><strong>(Oral Presentation (2<sup>nd</sup><span>&nbsp;</span>Prize))</strong></li>\n<li><strong></strong>Thermodynamic studies of ionic interactions of AAILs in aqueous solutions at 298.15 K,<span>&nbsp;</span><strong>P. Shinde<span>&nbsp;</span></strong>and D, H. Dagade, 50<sup>th</sup><span>&nbsp;</span>Annual convection of chemists, organized by<span>&nbsp;</span><strong>Indian Chemical Society</strong>, at Department of Chemistry, Panjab University,&nbsp; Chandigarh on 04<sup>th</sup><span>&nbsp;</span>-07<sup>th</sup><span>&nbsp;</span>&nbsp;Dec. 2013.<strong><span>&nbsp;</span>(Oral Presentation)</strong></li>\n<li><strong></strong>The volume and compressibilities studies of Lanthanum Chloride and Cerium Chloride in aqueous solutions containing 18-crown-6 at 298.15 K,<span>&nbsp;</span><strong>P</strong>.<span>&nbsp;</span><strong>Shinde&nbsp;<span>&nbsp;</span></strong>and&nbsp; R. R. Kumbhar<sup>*<span>&nbsp;</span></sup>National Seminar on Recent Advances in Synthetic Chemistry and Nanomaterials (RASCN)<strong><span>&nbsp;</span></strong>21<sup>st</sup><span>&nbsp;</span>-22<sup>nd</sup><span>&nbsp;</span>&nbsp;Jan 2012, Department of Chemistry,<span>&nbsp;</span><strong>Shivaji University, Kolhapur</strong>.<span>&nbsp;</span><strong>(Oral Presentation)</strong></li>\n<li><strong></strong>Studies of volume and compresibility properties of aqueous solutions of ionic liquids<strong><span>&nbsp;</span>P. Shinde</strong>, 48<sup>th</sup><span>&nbsp;</span>Annual convention of chemist and celebration of the international year of chemistry, organized by<span>&nbsp;</span><strong>Indian Chemical Society</strong><span>&nbsp;</span>at Department of Chemistry, University of Allahabad. Allahabad on 03<sup>rd</sup><span>&nbsp;</span>-07<sup>th</sup><span>&nbsp;</span>Dec. 2011.<strong><span>&nbsp;</span>(Oral Presentation)</strong></li>\n</ol>', '1', 0, 1, '', 299, '2025-09-23', 0),
