(3112, 78, 320, 0, 0, 0, 0, 0, '', '<p>Research Papers Presented</p>\n<ul>\n<li>Water quality monitoring of river Vainganga in Gondia district using microinvertebrates<br />Co-author: Harinkhede Pralhad, Ashok Manekar<br />Name of Seminar :Wetland-present status , ecology and conservation<br />Level :National<br />Period :12/08/2015-12/08/2015<br />Name of Organizers :M. D. College of Arts, Science and Commerce parel, Mumbai</li>\n</ul>\n<p></p>\n<ul>\n<li>Effect of cyclophosphamide on reproductive system and kidney of the albino rats<br />Co-author: Ashok Manekar.<br />Name of Conference :102nd Indian Science Congress.<br />Level :International<br />Period :03/01/2015-07/01/2015<br />Name of Organizers :Mumbai University, Kalina campus</li>\n</ul>', '1', 0, 1, '', 320, '2025-09-23', 0),
(3113, 79, 320, 0, 0, 0, 0, 0, '', '<p><strong>1. Role of Geographical Separation in Molecular Evolution of Giant Wood Spider (Nephila pilipes)</strong><br />Principal Investigator :Vishal Kadu<br />Co Investigator :NA<br />Period :20/04/2021 - 31/03/2022<br />Status :Completed<br />Funded By: Mumbai University under Minor Research Project</p>\n<p><br /><strong>2. Comparative study of two lakes (Powai and vihar) in Mumbai, with respect to variousphysico-chemical parameters and zooplankton diversity.</strong><br />Principal Investigator :Vitthal Dandwate<br />Co Investigator :Vishal Kadu<br />Period :20/11/2014 - 31/03/2015<br />Status :Completed<br />Funded By: Mumbai University under Minor Research Project</p>', '1', 0, 1, '', 320, '2025-09-23', 0),
(3114, 80, 320, 0, 0, 0, 0, 0, '', '<p>Recognised research guide from University of Mumbai in the Zoology subject.</p>', '1', 0, 1, '', 320, '2025-09-23', 0),
(3115, 81, 320, 0, 0, 0, 0, 0, '', '<p><strong>Research Papers Presented</strong></p>\n<ul>\n<li><strong>Water quality monitoring of river Vainganga in Gondia district using microinvertebrates</strong><br />Co-author: Harinkhede Pralhad, Ashok Manekar<br />Name of Seminar :Wetland-present status , ecology and conservation<br />Level :National<br />Period :12/08/2015-12/08/2015<br />Name of Organizers :M. D. College of Arts, Science and Commerce parel, Mumbai</li>\n</ul>\n<p></p>\n<ul>\n<li><strong>Effect of cyclophosphamide on reproductive system and kidney of the albino rats</strong><br />Co-author: Ashok Manekar.<br />Name of Conference :102nd Indian Science Congress.<br />Level :International<br />Period :03/01/2015-07/01/2015<br />Name of Organizers :Mumbai University, Kalina campus</li>\n</ul>', '1', 0, 1, '', 320, '2025-09-23', 0),
(3116, 95, 320, 0, 0, 0, 0, 0, '', '<p><strong>Published books:</strong></p>\n<p><strong>1. Practical Handbook of Genetics</strong><br />Year of publication: 2023<br />ISBN: 978-81-957566-6-7</p>\n<p><strong>2. Practical Handbook of Instrumentation and Biotechnology</strong><br />Year of publication: 2022<br />ISBN: 978-81-957566-1-2</p>', '1', 0, 1, '', 320, '2025-09-23', 0),
