(3315, 73, NULL, 0, 0, 0, 0, 0, '', '<table style=\"border-collapse: collapse; width: 100%; height: 126px;\" border=\"1\">\r\n<tbody>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.741%; height: 18px;\"><strong>&nbsp;Sr. No.&nbsp;</strong></td>\r\n<td style=\"width: 53.3712%; height: 18px;\"><strong>&nbsp;Name of Comittee&nbsp;</strong></td>\r\n<td style=\"width: 33.0587%; height: 18px;\"><strong>In Charge/ Member&nbsp;</strong></td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.741%; height: 18px;\">1.</td>\r\n<td style=\"width: 53.3712%; height: 18px;\">&nbsp;Green Club and Green-Audit&nbsp;</td>\r\n<td style=\"width: 33.0587%; height: 18px;\">co-ordinator&nbsp;</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.741%; height: 18px;\">2.</td>\r\n<td style=\"width: 53.3712%; height: 18px;\">&nbsp;Nature Club&nbsp;</td>\r\n<td style=\"width: 33.0587%; height: 18px;\">&nbsp;In -Charge</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.741%; height: 18px;\">3.</td>\r\n<td style=\"width: 53.3712%; height: 18px;\">&nbsp;Garden Committee</td>\r\n<td style=\"width: 33.0587%; height: 18px;\">Incharge&nbsp;</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.741%; height: 18px;\">4.</td>\r\n<td style=\"width: 53.3712%; height: 18px;\">&nbsp;Admission commitee ( UG and PG)</td>\r\n<td style=\"width: 33.0587%; height: 18px;\">&nbsp;Member</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.741%; height: 18px;\">5.</td>\r\n<td style=\"width: 53.3712%; height: 18px;\">&nbsp;Discipline committee&nbsp;</td>\r\n<td style=\"width: 33.0587%; height: 18px;\">&nbsp;Member&nbsp;</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 12.741%; height: 18px;\">6.</td>\r\n<td style=\"width: 53.3712%; height: 18px;\">&nbsp;Central Reseach facility committee&nbsp;</td>\r\n<td style=\"width: 33.0587%; height: 18px;\">&nbsp;Member&nbsp;</td>\r\n</tr>\r\n</tbody>\r\n</table>\r