(3328, 73, 337, 0, 0, 0, 0, 0, '', '<p>&nbsp;</p>\r\n<table style=\"border-collapse: collapse; width: 77.4818%; height: 232px;\" border=\"1\">\r\n<tbody>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 13.1263%; text-align: center; height: 18px;\">Academic Year</td>\r\n<td style=\"width: 86.2515%; text-align: center; height: 18px;\">Committee</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 13.1263%; height: 18px;\">2019-2020</td>\r\n<td style=\"width: 86.2515%; height: 18px; text-align: justify;\">\r\n<p style=\"margin: 0in;\">&nbsp; &nbsp; &nbsp;</p>\r\n<p style=\"margin: 0in;\">&nbsp; &nbsp; &nbsp; 1. Result Finalization</p>\r\n<p style=\"margin: 0in;\">&nbsp; &nbsp; &nbsp; 2. Gravity</p>\r\n<p style=\"margin: 0in;\">&nbsp; &nbsp; &nbsp; 3. Discipline</p>\r\n<p style=\"margin: 0in;\">&nbsp; &nbsp; &nbsp; 4. Cultural</p>\r\n<p style=\"margin: 0in;\">&nbsp; &nbsp; &nbsp; 5. Academic Prize distribution Function</p>\r\n</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 13.1263%; height: 10px;\">2020-2021</td>\r\n<td style=\"width: 86.2515%; height: 10px; text-align: justify;\">\r\n<ol>\r\n<li>Online Teaching</li>\r\n<li>Mentor-Mentee Scheme</li>\r\n<li>Maitri Sangh</li>\r\n<li>Discipline</li>\r\n<li>Online examination</li>\r\n</ol>\r\n</td>\r\n</tr>\r\n<tr style=\"height: 56px;\">\r\n<td style=\"width: 13.1263%; height: 56px;\">2021-2022</td>\r\n<td style=\"width: 86.2515%; height: 56px; text-align: justify;\">\r\n<ol>\r\n<li>Research</li>\r\n<li>Online Teaching Attendance</li>\r\n<li>IQAC Sub-Committee</li>\r\n<li>Mentor-Mentee Scheme</li>\r\n<li>NSS Advisory</li>\r\n<li>Library</li>\r\n<li>Hospitality</li>\r\n<li>Garden</li>\r\n<li>Discipline</li>\r\n<li>Equal Opportunity Centre</li>\r\n<li>Question Bank Uploading</li>\r\n<li>Competition Organization Committee (Vigyan Sarvatra Pujyate)</li>\r\n</ol>\r\n</td>\r\n</tr>\r\n<tr style=\"height: 75px;\">\r\n<td style=\"width: 13.1263%; height: 75px;\">2022-2023</td>\r\n<td style=\"width: 86.2515%; height: 75px; text-align: justify;\">\r\n<ol>\r\n<li>Add on Courses In-charge for Science stream</li>\r\n<li>IQAC Sub-Committee</li>\r\n<li>Admission</li>\r\n<li>Organizing Committee for inaugural function of Central Research Facility and training for utilization of instuments</li>\r\n<li>Science Association and Gravity</li>\r\n<li>Garden</li>\r\n<li>Research</li>\r\n<li>Scholarship</li>\r\n<li>Library</li>\r\n<li>Equal Opportunity Centre</li>\r\n<li>Discipline</li>\r\n<li>Hospitality Committee for Inter-Institutional Research Conclave: 2022-23</li>\r\n</ol>\r\n</td>\r\n</tr>\r\n<tr style=\"height: 37px;\">\r\n<td style=\"width: 13.1263%; height: 37px;\">2023-2024</td>\r\n<td style=\"width: 86.2515%; height: 37px; text-align: justify;\">\r\n<ol>\r\n<li>Admission</li>\r\n<li>IQAC Sub-Committee</li>\r\n<li>Equal Opportunity Centre</li>\r\n<li>Add on Courses In-charge</li>\r\n<li>Green audit</li>\r\n<li>Library</li>\r\n<li>Maitri Sangh</li>\r\n<li>Cultural -Dance Association</li>\r\n<li>Gymkhana Managing</li>\r\n<li>Research</li>\r\n<li>Discipline</li>\r\n<li>Garden</li>\r\n<li>Science Association and Gravity</li>\r\n</ol>\r\n</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 13.1263%; height: 18px;\">2024-2025</td>\r\n<td style=\"width: 86.2515%; height: 18px; text-align: justify;\">\r\n<ol>\r\n<li>Admission</li>\r\n<li>IQAC Sub-Committee</li>\r\n<li>Add on Courses In-charge</li>\r\n<li>Green audit</li>\r\n<li>Library</li>\r\n<li>Cultural</li>\r\n<li>Research</li>\r\n<li>Discipline</li>\r\n<li>Garden</li>\r\n<li>Science Association and Gravity</li>\r\n</ol>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 13.1263%;\">2025-2026</td>\r\n<td style=\"width: 86.2515%; text-align: justify;\">\r\n<p>1. Green Club and Green Audit (Green Club Faculty Coordinator)</p>\r\n<p>2. NSS (NSS Programme Officer)</p>\r\n<p>3. Research and Development&nbsp; Cell</p>\r\n<p>4. Admission</p>\r\n<p>5. IQAC Sub-Committee</p>\r\n<p>6. Library</p>\r\n<p>7. Discipline</p>\r\n<p>8. Garden</p>\r\n<p>9. Gymkhana Managing Committee</p>\r\n<p>10. NSS Advisory Committee</p>\r\n<p>11. Maitri Sangh</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 13.1263%;\">2026-2027</td>\r\n<td style=\"width: 86.2515%; text-align: justify;\">\r\n<ol>\r\n<li>Examination Committee</li>\r\n<li>Garden Committee</li>\r\n<li>Admission</li>\r\n<li>Gymkhana Managing Committee</li>\r\n<li>Discipline</li>\r\n<li>Maitri Sangh</li>\r\n<li>Equal opportunity Committee</li>\r\n</ol>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>', '1', 0, 1, '', 337, '2025-09-23', 0),
