(3707, 103, 304, 0, 0, 0, 0, 0, '', '<p><strong><u>Subjects Undertaken:</u></strong></p>\n<p><strong><u><span>&nbsp;</span></u></strong></p>\n<ol>\n<li><span>Applied Mathematics </span></li>\n<li><span>Computational Mathematics</span></li>\n<li><span>Logic, discrete mathematics </span></li>\n<li><span>Quantitative techniques</span></li>\n<li><span>Data Structure</span></li>\n<li><span>E-Commerce</span></li>\n<li><span>Computer Simulation and Modeling(M.Sc I.T)</span></li>\n<li><span>Computer oriented statistical techniques</span></li>\n<li><span>Group Theory</span></li>\n<li><span>Ring Theory</span></li>\n<li><span>Numerical Analysis</span></li>\n<li><span>Calculus</span></li>\n<li><span>Linear Algera</span></li>\n<li><span>Abstract Algebra</span></li>\n</ol>\n<p><span>&nbsp;</span></p>\n<p><strong>Areas of Interest:</strong><span> Graph Theory, Algebra, Real and Complex Analysis.</span></p>', '1', 0, 1, '', 304, '2025-09-23', 0),
(3708, 103, 305, 0, 0, 0, 0, 0, '', '<h3 data-start=\"81\" data-end=\"111\" class=\"\"><span style=\"font-family: \'times new roman\', times, serif;\"><strong data-start=\"85\" data-end=\"111\">Area of Specialization</strong></span></h3>\n<ol data-start=\"113\" data-end=\"1780\">\n<li data-start=\"320\" data-end=\"524\" class=\"\">\n<p data-start=\"323\" data-end=\"524\" class=\"\"><span style=\"font-family: \'times new roman\', times, serif;\"><strong data-start=\"323\" data-end=\"364\">Microbial Physiology and Biochemistry</strong></span><br data-start=\"364\" data-end=\"367\" /><span style=\"font-family: \'times new roman\', times, serif;\">Expertise in the physiological functions of microorganisms and the biochemical pathways involved in their growth, metabolism, and industrial applications.</span></p>\n</li>\n<li data-start=\"526\" data-end=\"747\" class=\"\">\n<p data-start=\"529\" data-end=\"747\" class=\"\"><span style=\"font-family: \'times new roman\', times, serif;\"><strong data-start=\"529\" data-end=\"572\">Siderophore Production and Applications</strong></span><br data-start=\"572\" data-end=\"575\" /><span style=\"font-family: \'times new roman\', times, serif;\">Specialization in the production of siderophores by microorganisms, which play a crucial role in iron acquisition, plant growth promotion, and agricultural applications.</span></p>\n</li>\n<li data-start=\"749\" data-end=\"967\" class=\"\">\n<p data-start=\"752\" data-end=\"967\" class=\"\"><span style=\"font-family: \'times new roman\', times, serif;\"><strong data-start=\"752\" data-end=\"805\">Biochemical Characterization of Microbial Enzymes</strong></span><br data-start=\"805\" data-end=\"808\" /><span style=\"font-family: \'times new roman\', times, serif;\">In-depth knowledge in the isolation, characterization, and application of microbial enzymes, particularly in the areas of biodegradation and bioremediation.</span></p>\n</li>\n<li data-start=\"969\" data-end=\"1138\" class=\"\">\n<p data-start=\"972\" data-end=\"1138\" class=\"\"><span style=\"font-family: \'times new roman\', times, serif;\"><strong data-start=\"972\" data-end=\"1002\">Environmental Microbiology</strong></span><br data-start=\"1002\" data-end=\"1005\" /><span style=\"font-family: \'times new roman\', times, serif;\">Specializing in the role of microorganisms in natural and contaminated environments, including waste treatment and bioremediation.</span></p>\n</li>\n<li data-start=\"1546\" data-end=\"1780\" class=\"\">\n<p data-start=\"1549\" data-end=\"1780\" class=\"\"><span style=\"font-family: \'times new roman\', times, serif;\"><strong data-start=\"1549\" data-end=\"1577\">Industrial Biotechnology</strong></span><br data-start=\"1577\" data-end=\"1580\" /><span style=\"font-family: \'times new roman\', times, serif;\">Specializing in the application of biotechnology in industrial processes, focusing on bio-based production, fermentation technologies, and optimization of bioprocesses for large-scale applications.</span></p>\n</li>\n</ol>', '1', 0, 1, '', 305, '2025-09-23', 0),
(3709, 103, 306, 0, 0, 0, 0, 0, '', '<ol>\n<li>\n<p><span style=\"font-family: \'times new roman\', times, serif;\"><strong>Microfluidics&nbsp;</strong></span></p>\n</li>\n<li>\n<p><span style=\"font-family: \'times new roman\', times, serif;\"><strong>Microbial Enzyme Technology</strong></span></p>\n</li>\n<li>\n<p><span style=\"font-family: \'times new roman\', times, serif;\"><strong>Bioflavors and Biofragrances Synthesis</strong></span></p>\n</li>\n<li>\n<p><span style=\"font-family: \'times new roman\', times, serif;\"><strong>Environmental Microbiology and Pathogen Detection</strong></span></p>\n</li>\n<li>\n<p><span style=\"font-family: \'times new roman\', times, serif;\"><strong>Biotechnology Applications in Sustainable Agriculture</strong></span></p>\n</li>\n</ol>', '1', 0, 1, '', 306, '2025-09-23', 0),
