INSERT INTO `tbl_section_info` (`dsi_id`, `dsi_dsm_id`, `dsi_dsl_id`, `dsi_asl_id`, `dsi_ayl_id`, `dsi_assl_id`, `dsi_lib_id`, `dsi_res_id`, `dsi_new_content`, `dsi_content`, `dsi_is_display_on_website`, `dsm_order`, `approve_bit`, `rejected_reason`, `dsi_user_id`, `dsi_time`, `delete_bit`) VALUES
(4489, 113, 49, 0, 0, 0, 0, 0, '<p><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">A <strong data-start=\"32\" data-end=\"58\">Classroom Plant Museum</strong> is an innovative, student-centric learning space where preserved plant specimens, models, charts, and value-added products are systematically displayed for teaching and demonstration. It transforms a regular classroom into a <strong data-start=\"284\" data-end=\"318\">mini botanical resource center</strong> that supports experiential learning.</span></p>\n<p><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">A Classroom Plant Museum reflects the department&rsquo;s commitment to <strong data-start=\"2017\" data-end=\"2091\">innovative teaching, conservation awareness, and experiential learning</strong>, especially valuable in autonomous and NEP-aligned curricula.</span></p>\n<h2 data-start=\"622\" data-end=\"664\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">Sections of a Classroom Plant Museum</span></h2>\n<h3 data-start=\"666\" data-end=\"693\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">Herbarium Section</span></h3>\n<ul data-start=\"694\" data-end=\"828\">\n<li data-start=\"694\" data-end=\"731\">\n<p data-start=\"696\" data-end=\"731\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">Properly mounted herbarium sheets</span></p>\n</li>\n<li data-start=\"732\" data-end=\"757\">\n<p data-start=\"734\" data-end=\"757\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">Local flora specimens</span></p>\n</li>\n<li data-start=\"758\" data-end=\"789\">\n<p data-start=\"760\" data-end=\"789\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">Medicinal plant collections</span></p>\n</li>\n<li data-start=\"790\" data-end=\"828\">\n<p data-start=\"792\" data-end=\"828\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">Digital QR-coded herbarium records</span></p>\n</li>\n</ul>\n<h3 data-start=\"830\" data-end=\"867\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">&nbsp;Morphology &amp; Anatomy Corner</span></h3>\n<ul data-start=\"868\" data-end=\"1008\">\n<li data-start=\"868\" data-end=\"902\">\n<p data-start=\"870\" data-end=\"902\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">Root, stem, leaf modifications</span></p>\n</li>\n<li data-start=\"903\" data-end=\"944\">\n<p data-start=\"905\" data-end=\"944\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">Flower types and inflorescence models</span></p>\n</li>\n<li data-start=\"945\" data-end=\"976\">\n<p data-start=\"947\" data-end=\"976\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">Permanent slides of tissues</span></p>\n</li>\n<li data-start=\"977\" data-end=\"1008\">\n<p data-start=\"979\" data-end=\"1008\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">Charts and labeled diagrams</span></p>\n</li>\n</ul>\n<h3 data-start=\"1010\" data-end=\"1043\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">&nbsp;Economic Botany Section</span></h3>\n<ul data-start=\"1044\" data-end=\"1120\">\n<li data-start=\"1044\" data-end=\"1076\">\n<p data-start=\"1046\" data-end=\"1076\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">Fibers, oils, spices, pulses</span></p>\n</li>\n<li data-start=\"1077\" data-end=\"1095\">\n<p data-start=\"1079\" data-end=\"1095\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">Timber samples</span></p>\n</li>\n<li data-start=\"1096\" data-end=\"1120\">\n<p data-start=\"1098\" data-end=\"1120\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">Plant-based products</span></p>\n</li>\n</ul>\n<h3 data-start=\"1122\" data-end=\"1169\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">&nbsp;Algae, Fungi Bryophytes ,&nbsp; Pteridophytes &amp; Gymnosperms Collection</span></h3>\n<ul data-start=\"1170\" data-end=\"1243\">\n<li data-start=\"1170\" data-end=\"1193\">\n<p data-start=\"1172\" data-end=\"1193\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">Preserved specimens</span></p>\n</li>\n<li data-start=\"1194\" data-end=\"1215\">\n<p data-start=\"1196\" data-end=\"1215\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">Life cycle charts</span></p>\n</li>\n<li data-start=\"1216\" data-end=\"1243\">\n<p data-start=\"1218\" data-end=\"1243\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">Field-collected samples</span></p>\n</li>\n</ul>\n<h3 data-start=\"1245\" data-end=\"1275\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">&nbsp;Seed &amp; Fruit Display</span></h3>\n<ul data-start=\"1276\" data-end=\"1355\">\n<li data-start=\"1276\" data-end=\"1303\">\n<p data-start=\"1278\" data-end=\"1303\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">Monocot and dicot seeds</span></p>\n</li>\n<li data-start=\"1304\" data-end=\"1329\">\n<p data-start=\"1306\" data-end=\"1329\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">Dry and fleshy fruits</span></p>\n</li>\n<li data-start=\"1330\" data-end=\"1355\">\n<p data-start=\"1332\" data-end=\"1355\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">Dispersal adaptations</span></p>\n</li>\n</ul>\n<h3 data-start=\"1357\" data-end=\"1384\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">6️⃣ Live Plant Corner</span></h3>\n<ul data-start=\"1385\" data-end=\"1459\">\n<li data-start=\"1385\" data-end=\"1412\">\n<p data-start=\"1387\" data-end=\"1412\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">Potted medicinal plants</span></p>\n</li>\n<li data-start=\"1413\" data-end=\"1427\">\n<p data-start=\"1415\" data-end=\"1427\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">Succulents</span></p>\n</li>\n<li data-start=\"1428\" data-end=\"1459\">\n<p data-start=\"1430\" data-end=\"1459\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">Indoor air-purifying plants</span></p>\n</li>\n</ul>', '<p><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">A <strong data-start=\"32\" data-end=\"58\">Classroom Plant Museum</strong> is an innovative, student-centric learning space where preserved plant specimens, models, charts, and value-added products are systematically displayed for teaching and demonstration. It transforms a regular classroom into a <strong data-start=\"284\" data-end=\"318\">mini botanical resource center</strong> that supports experiential learning.</span></p>\n<p><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">A Classroom Plant Museum reflects the department&rsquo;s commitment to <strong data-start=\"2017\" data-end=\"2091\">innovative teaching, conservation awareness, and experiential learning</strong>, especially valuable in autonomous and NEP-aligned curricula.</span></p>\n<h2 data-start=\"622\" data-end=\"664\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">Sections of a Classroom Plant Museum</span></h2>\n<h3 data-start=\"666\" data-end=\"693\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">Herbarium Section</span></h3>\n<ul data-start=\"694\" data-end=\"828\">\n<li data-start=\"694\" data-end=\"731\">\n<p data-start=\"696\" data-end=\"731\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">Properly mounted herbarium sheets</span></p>\n</li>\n<li data-start=\"732\" data-end=\"757\">\n<p data-start=\"734\" data-end=\"757\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">Local flora specimens</span></p>\n</li>\n<li data-start=\"758\" data-end=\"789\">\n<p data-start=\"760\" data-end=\"789\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">Medicinal plant collections</span></p>\n</li>\n<li data-start=\"790\" data-end=\"828\">\n<p data-start=\"792\" data-end=\"828\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">Digital QR-coded herbarium records</span></p>\n</li>\n</ul>\n<h3 data-start=\"830\" data-end=\"867\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">&nbsp;Morphology &amp; Anatomy Corner</span></h3>\n<ul data-start=\"868\" data-end=\"1008\">\n<li data-start=\"868\" data-end=\"902\">\n<p data-start=\"870\" data-end=\"902\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">Root, stem, leaf modifications</span></p>\n</li>\n<li data-start=\"903\" data-end=\"944\">\n<p data-start=\"905\" data-end=\"944\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">Flower types and inflorescence models</span></p>\n</li>\n<li data-start=\"945\" data-end=\"976\">\n<p data-start=\"947\" data-end=\"976\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">Permanent slides of tissues</span></p>\n</li>\n<li data-start=\"977\" data-end=\"1008\">\n<p data-start=\"979\" data-end=\"1008\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">Charts and labeled diagrams</span></p>\n</li>\n</ul>\n<h3 data-start=\"1010\" data-end=\"1043\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">&nbsp;Economic Botany Section</span></h3>\n<ul data-start=\"1044\" data-end=\"1120\">\n<li data-start=\"1044\" data-end=\"1076\">\n<p data-start=\"1046\" data-end=\"1076\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">Fibers, oils, spices, pulses</span></p>\n</li>\n<li data-start=\"1077\" data-end=\"1095\">\n<p data-start=\"1079\" data-end=\"1095\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">Timber samples</span></p>\n</li>\n<li data-start=\"1096\" data-end=\"1120\">\n<p data-start=\"1098\" data-end=\"1120\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">Plant-based products</span></p>\n</li>\n</ul>\n<h3 data-start=\"1122\" data-end=\"1169\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">&nbsp;Algae, Fungi Bryophytes ,&nbsp; Pteridophytes &amp; Gymnosperms Collection</span></h3>\n<ul data-start=\"1170\" data-end=\"1243\">\n<li data-start=\"1170\" data-end=\"1193\">\n<p data-start=\"1172\" data-end=\"1193\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">Preserved specimens</span></p>\n</li>\n<li data-start=\"1194\" data-end=\"1215\">\n<p data-start=\"1196\" data-end=\"1215\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">Life cycle charts</span></p>\n</li>\n<li data-start=\"1216\" data-end=\"1243\">\n<p data-start=\"1218\" data-end=\"1243\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">Field-collected samples</span></p>\n</li>\n</ul>\n<h3 data-start=\"1245\" data-end=\"1275\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">&nbsp;Seed &amp; Fruit Display</span></h3>\n<ul data-start=\"1276\" data-end=\"1355\">\n<li data-start=\"1276\" data-end=\"1303\">\n<p data-start=\"1278\" data-end=\"1303\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">Monocot and dicot seeds</span></p>\n</li>\n<li data-start=\"1304\" data-end=\"1329\">\n<p data-start=\"1306\" data-end=\"1329\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">Dry and fleshy fruits</span></p>\n</li>\n<li data-start=\"1330\" data-end=\"1355\">\n<p data-start=\"1332\" data-end=\"1355\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">Dispersal adaptations</span></p>\n</li>\n</ul>\n<h3 data-start=\"1357\" data-end=\"1384\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">6️⃣ Live Plant Corner</span></h3>\n<ul data-start=\"1385\" data-end=\"1459\">\n<li data-start=\"1385\" data-end=\"1412\">\n<p data-start=\"1387\" data-end=\"1412\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">Potted medicinal plants</span></p>\n</li>\n<li data-start=\"1413\" data-end=\"1427\">\n<p data-start=\"1415\" data-end=\"1427\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">Succulents</span></p>\n</li>\n<li data-start=\"1428\" data-end=\"1459\">\n<p data-start=\"1430\" data-end=\"1459\"><span style=\"font-family: \'times new roman\', times, serif; font-size: 12pt;\">Indoor air-purifying plants</span></p>\n</li>\n</ul>', '0', 0, 0, '', 2, '2026-08-13', 0),
