(4855, 108, 357, 0, 0, 0, 0, 0, '', '<p>Lecturer,</p>\n<p>M.com , SET.</p>\n<p>He is a experienced lecturer in commerce with three years of teaching experience. He is speacialied in the marketing, management, organsiational behaviour subjects.&nbsp;</p>', '1', 0, 1, '', 357, '2025-09-23', 0),
(4856, 71, 358, 0, 0, 0, 0, 0, '', '<ul>\n<li>SUO(Senior Under Officer) Rank in NCC</li>\n<li>Best Cadet in NCC (2016-17)</li>\n<li>Best Administrative Senior in NCC camp (2016-17)</li>\n<li>Marketing Head of the conference event named COLLOQUIUM 2017</li>\n<li>Event Head of SYNERGY FEST</li>\n<li>Secretary in Rotaract Club of Mumbai BKC</li>\n</ul>', '1', 0, 1, '', 358, '2025-09-23', 0),
