(4858, 75, 358, 0, 0, 0, 0, 0, '', '<ul>\n<li>Jaro Education as Management Trainee (2017-2018)</li>\n<li>Mahindra Holidays and Resorts India Ltd as Relationship Manager (2018-2020)</li>\n<li>Motilal Oswal Financial Services Ltd as Equity Advisor (2020-2021)</li>\n<li>PR Financial Services as Onwer (2021- Present)</li>\n<li>Sathaye College as Lecturer (2024- Present)</li>\n</ul>', '1', 0, 1, '', 358, '2025-09-23', 0),
(4859, 76, NULL, 0, 0, 0, 0, 0, '', '', '1', 0, 1, '', 358, '2025-09-23', 0),
(4860, 77, 358, 0, 0, 0, 0, 0, '', '<ul>\n<li>Invited to speak on the topic of SSB(Service Selection Board) in Sathaye College in 2022.</li>\n<li>Invited to speak on the topic of Basics of Finance, Savings, Investment and Budgeting in St Xavier\'s Group of School in 2023.</li>\n</ul>', '1', 0, 1, '', 358, '2025-09-23', 0),
