(5085, 71, 370, 0, 0, 0, 0, 0, '', '<ul>\n<li>Secured <strong>1<sup>st</sup> rank</strong> in Sathaye College at <strong>T.Y.B.Sc. (Botany)</strong> with<strong> </strong>grade A/ CGPA 6.92<strong> </strong>(Mumbai University exam Sem. V &amp; VI), 2017 along with <strong>Fourth</strong> rank in <strong>Mumbai University</strong>.</li>\n<li>Secured <strong>1<sup>st</sup> rank</strong> in <strong>M.Sc. (Part I &ndash; II) </strong>with grade A+ (CGPA 9.54)<strong> </strong>in G. N. Khalsa College<strong> (</strong>Mumbai University examination), 2019.</li>\n<li>Awarded Dr. K. U. Naram award for securing 1<sup>st</sup> rank at PG University Exam on World Food<strong> </strong>Day at<strong> ICT by AFST(I) Mumbai</strong>, Oct., 2019.</li>\n<li>Qualified <strong>CSIR UGC NET Lectureship/Assistant Professor</strong> (<strong>AIR - 66</strong>) in&nbsp; June, 2020 examination (Life Sciences).</li>\n<li>Awarded Elite + Gold type certificate from National Institute of Technical Teachers&rsquo; Training &amp; Research <strong>(NITTTR), Chennai </strong>for successful completion of the 3 credit Swayam course on \"<strong>Student Psychology</strong>\" &amp; passing the exam with <strong>96%.</strong><strong></strong></li>\n</ul>', '1', 0, 1, '', 370, '2025-09-23', 0),
(5086, 73, 370, 0, 0, 0, 0, 0, '', '', '0', 0, 1, '', 370, '2025-09-23', 0),
(5087, 75, 370, 0, 0, 0, 0, 0, '', '<p><strong>Teaching experience</strong>: <strong>03 years</strong>&nbsp;(Sathaye college: from July 2024 &amp; G. N. Khalsa college: 2021 - 2023)</p>\n<p><strong>Internship</strong>: At <strong>Food &amp; Drugs Administration</strong>, Maharashtra State (2018) :- Acquired elementary skills to operate analytical instruments like HPLC, HPTLC, GC; learnt procedures &amp; processes adopted for standardization as well as analysis of food articles.</p>', '1', 0, 1, '', 370, '2025-09-23', 0),
