(5196, 98, 375, 0, 0, 0, 0, 0, '', '<p>I have completed a Workshop on Flipped Learning organized by Sathaye College from 16/01/2025 to 06/03/2025.&nbsp;</p>', '1', 0, 1, '', 375, '2025-09-23', 0),
(5197, 103, NULL, 0, 0, 0, 0, 0, '', '', '1', 0, 1, '', 375, '2025-09-23', 0),
(5198, 104, 375, 0, 0, 0, 0, 0, '', '<p>15 July 2024</p>', '1', 0, 1, '', 375, '2025-09-23', 0),
(5199, 107, NULL, 0, 0, 0, 0, 0, '', '', '1', 0, 1, '', 375, '2025-09-23', 0),
(5200, 108, 375, 0, 0, 0, 0, 0, '', '<p>I have completed my BSc (Mathematics) from D G&nbsp; Ruparel College in May 2021 and my MSc (Mathematics) from Indian Institute of Technology Bhubaneswar in May 2023. I have worked as an Assistant Professor in Mathatematics at D G Ruparel College from Dec 2023 to April 2024. I am currently working as an Assistant Professor in Department of Mathematics, Sathaye College.</p>', '1', 0, 1, '', 375, '2025-09-23', 0),
(5201, 71, NULL, 0, 0, 0, 0, 0, '', '', '1', 0, 1, '', 376, '2025-09-23', 0),
(5202, 73, 376, 0, 0, 0, 0, 0, '', '<p>&bull; Member Secretory - BOS</p>\n<p>&bull; Sub-committee Member - IQAC (Criteria IV Financial resources and Management)&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</p>\n<p>&bull; Sub-comittee member - Admission committee</p>\n<p>&bull; Sub-comittee member -Prospectus committee.</p>', '1', 0, 1, '', 376, '2025-09-23', 0),
(5203, 75, 376, 0, 0, 0, 0, 0, '', '<ol>\n<li style=\"text-align: justify; line-height: 1.5;\">Assistant Professor in Mathematics, PTVA&rsquo;s Sathaye College, Vile Parle (East), Mumbai,&nbsp; Maharashtra, India <strong>from 04 January 2025 to till date.</strong></li>\n<li style=\"text-align: justify; line-height: 1.5;\">Assistant Professor, Department of Mathematics, Science College under Swami Ramanand Teerth Marathwada University, Nanded. Maharashtra, India&nbsp;<strong>from August 2017 to April 2018 and August 2019 to April 2021.</strong></li>\n<li style=\"text-align: justify; line-height: 1.5;\">Lecturer in Mathematics, Shri Shivaji Junior College, Manik Nagar Nanded From<strong> from June 2016 to May 2020.</strong></li>\n</ol>', '1', 0, 1, '', 376, '2025-09-23', 0),
