(5839, 71, 448, 0, 0, 0, 0, 0, '', '<ul>\n<li>M.Sc. Zoology (2014) from Savitribai Phule Pune University, Pune.</li>\n<li>MH-SET Life Sciences (2014) conducted by UGC and Savitribai Phule Pune University.</li>\n<li>Awarded Ph.D Zoology (2022) from department of Zoology, Savitribai Phule Pune University, Pune.</li>\n<li>Published three research articles in international research journals.</li>\n<li>Published one research article in National Journal.</li>\n<li>Best poster presentation award (March 2021) for the research entitled \"Plumbagin suppresses RANKL-induced osteoclast differentiation Via inhibiting NFATc1 translocation\", presented at International conference on Fundamental and Applied Sciences, Bhartiya Vidya Bhavan\'s College, Mumbai.</li>\n</ul>\n<h1></h1>', '1', 0, 1, '', 448, '2025-09-23', 0),
(5840, 73, 448, 0, 0, 0, 0, 0, '', '<p>1) Member of National Institutional Ranking Framework (NIRF) Committee</p>\r\n<p>2) Member of IQAC Criteria V</p>\r\n<p>3) Member of Admission Committee</p>\r\n<p>4)&nbsp;Member of Board of Studies (BOS) in Zoology.</p>\r\n<p>5) Member of Astra Committee</p>\r\n<p>6) Member of Alumni Cultural Committee</p>\r\n<p>7) Member of Dance Association</p>\r\n<p>8) Member of Career Conclave Committee</p>\r\n<p>&nbsp;</p>', '1', 0, 1, '', 448, '2025-09-23', 0),
(5841, 75, 448, 0, 0, 0, 0, 0, '', '<table width=\"491\">\n<tbody>\n<tr>\n<td width=\"142\">\n<p><strong>Designation</strong></p>\n</td>\n<td width=\"217\">\n<p><strong>Name of College/ Institute</strong></p>\n</td>\n<td width=\"132\">\n<p><strong>Duration</strong></p>\n</td>\n</tr>\n<tr>\n<td width=\"142\">\n<p>&nbsp;Assistant Professor</p>\n</td>\n<td width=\"217\">\n<p>MES Abasaheb Garware college, Pune</p>\n</td>\n<td width=\"132\">\n<p>August 2014 to March 2015</p>\n</td>\n</tr>\n<tr>\n<td width=\"142\">\n<p>Guest Lecturer</p>\n</td>\n<td width=\"217\">\n<p>Symbiosis School of Liberal Arts, Pune</p>\n</td>\n<td width=\"132\">\n<p>March 2024</p>\n</td>\n</tr>\n<tr>\n<td width=\"142\">\n<p>Assistant professor</p>\n</td>\n<td width=\"217\">\n<p>Indira College of Arts, Commerce and Science, Pune</p>\n</td>\n<td width=\"132\">\n<p>July 2024 to December 2024</p>\n</td>\n</tr>\n<tr>\n<td width=\"142\">\n<p>Assistant professor</p>\n</td>\n<td width=\"217\">\n<p>PTVA&rsquo;s Sathaye College, Vile Parle, Mumbai</p>\n</td>\n<td width=\"132\">\n<p>January 2025 to present</p>\n</td>\n</tr>\n</tbody>\n</table>', '1', 0, 1, '', 448, '2025-09-23', 0),
