(6188, 131, 360, 0, 0, 0, 0, 0, '', '<p>\"In a world of connections, be the spark!\"</p>', '1', 0, 1, '', 360, '2025-09-23', 0),
(6189, 131, NULL, 0, 0, 0, 0, 0, '', '', '1', 0, 1, '', 364, '2025-09-23', 0),
(6190, 131, 365, 0, 0, 0, 0, 0, '', '<div dir=\"auto\"><strong>Social Activities</strong></div>\n<div dir=\"auto\"></div>\n<ul style=\"list-style-type: circle;\">\n<li dir=\"auto\">Participated and won multiple District-Level Elocution Competition</li>\n<li dir=\"auto\">Served as an NCC cadet (2017&ndash;2020), achieving the Rank of Sergeant and winning a Gold Medal in Speech at CATC Camp</li>\n<li dir=\"auto\">Organized and hosted college fests and psychology-related workshops</li>\n<li dir=\"auto\">Active involvement in student mentorship and peer-support initiatives</li>\n<li dir=\"auto\">Volunteered in mental health awareness programs and community counseling events</li>\n</ul>\n<div dir=\"auto\"></div>\n<div dir=\"auto\"><strong>Interests</strong></div>\n<ul style=\"list-style-type: circle;\">\n<li dir=\"auto\">Reading psychological literature and self-help books</li>\n<li dir=\"auto\">Acting and stage performance</li>\n<li dir=\"auto\">Traveling and exploring cultures</li>\n<li dir=\"auto\">Public speaking and debates</li>\n<li dir=\"auto\">Creative writing and content development</li>\n</ul>', '1', 0, 1, '', 365, '2025-09-23', 0),
