(9671, 95, NULL, 0, 0, 0, 0, 0, '<p><em><strong>Anthology Contributions:</strong></em></p>\r\n<p>1. She Raises, India Shines (2025), Blue Cloud Publishers.<br />2. Be Limitless (2024), Blue Cloud Publishers.<br />3. Sky Is the Limit (2024), Blue Cloud Publishers.</p>', '', '1', 0, 0, '', 558, '0000-00-00', 0),
(9672, 96, NULL, 0, 0, 0, 0, 0, '', '<ol>\r\n<li>National Webinar \"Tourism in India: Explore the Unexplored\" by Deccan Education Society\'s, Kirti M. Doongursee College of Arts, Science and Commerce, Mumbai, 2021.</li>\r\n<li>RUSA- sponsored Webinar-cum-conference titled, \"Mindfulness Through Literature\" by St.Xavier\'s College, Department of English, Mumbai,2021.</li>\r\n<li>RUSA- sponsored Webinar-cum-conference titled, \"The Creative (Complex) Joy of Translation: An Introduction to Translation Studies\" by St.Xavier\'s College, Department of English, Mumbai,2021.</li>\r\n<li>Hilary Nesi - Webinar on \"Classroom genres and University genres:getting the balance right\" by Cambridge University Press, 2020.</li>\r\n</ol>', '1', 0, 1, '', 558, '0000-00-00', 0),
(9673, 97, NULL, 0, 0, 0, 0, 0, '', '<p><strong>Anthology Contributions:</strong></p>\r\n<p>1. She Raises, India Shines (2025), Blue Cloud Publishers.<br />2. Be Limitless (2024), Blue Cloud Publishers.<br />3. Sky Is the Limit (2024), Blue Cloud Publishers.</p>', '1', 0, 1, '', 558, '0000-00-00', 0),
