INSERT INTO `tbl_section_info` (`dsi_id`, `dsi_dsm_id`, `dsi_dsl_id`, `dsi_asl_id`, `dsi_ayl_id`, `dsi_assl_id`, `dsi_lib_id`, `dsi_res_id`, `dsi_new_content`, `dsi_content`, `dsi_is_display_on_website`, `dsm_order`, `approve_bit`, `rejected_reason`, `dsi_user_id`, `dsi_time`, `delete_bit`) VALUES
(9780, 203, 58, 0, 0, 0, 0, 0, '', '<h4><strong>Vision of Department :</strong></h4>\n<p><strong>Vision for UG:</strong></p>\n<p>To be a centre of excellence in historical studies by fostering critical inquiry, research, ethical values, and an informed understanding of the past, enabling students to appreciate diverse cultures, preserve heritage, and contribute responsibly to society and the nation.</p>\n<hr />\n<h4><strong>Mission of Department :</strong></h4>\n<p><strong>Mission for UG:</strong></p>\n<ol>\n<li>To impart quality education in History by developing a comprehensive understanding of historical events, processes, and historiography at local, national, and global levels.\n<table style=\"border-collapse: collapse; width: 861px;\" border=\"0\" width=\"64\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr style=\"height: 15.0pt;\">\n<td class=\"xl64\" style=\"height: 15pt; width: 859px;\" width=\"64\" height=\"20\">2. To cultivate critical thinking, analytical reasoning, and effective communication skills<span class=\"font0\"> through the study of historical sources, interpretation, and evidence-based learning.</span></td>\n</tr>\n<tr style=\"height: 15.0pt;\">\n<td class=\"xl64\" style=\"height: 15pt; width: 859px;\" height=\"20\">3. To promote historical research, interdisciplinary learning, and digital literacy<span class=\"font0\"> through archival studies, field visits, projects, and heritage documentation.</span></td>\n</tr>\n<tr style=\"height: 15.0pt;\">\n<td class=\"xl64\" style=\"height: 15pt; width: 859px;\" height=\"20\">4. To instill ethical values, constitutional principles, cultural sensitivity, and respect for diversity<span class=\"font0\">, encouraging responsible citizenship and social harmony.</span></td>\n</tr>\n</tbody>\n</table>\n</li>\n</ol>\n<hr />\n<h4><strong>Program Outcomes (PO) :</strong></h4>\n<table width=\"591\">\n<tbody>\n<tr>\n<td width=\"64\">PO No.</td>\n<td width=\"527\">PO Statement&nbsp;</td>\n</tr>\n<tr>\n<td>1</td>\n<td width=\"527\">Disciplinary Knowledge: Demonstrate an understanding of social, political, economic, cultural, historical and geographical aspects of society and appreciate diverse civilizations and cultures by considering individual and collective human perspectives that influence individual behaviour and social life.</td>\n</tr>\n<tr>\n<td>2</td>\n<td width=\"527\">Communication Skills: Communicate effectively using appropriate language and style, present ideas clearly in academic, creative, and professional contexts; and engage with diverse audiences through oral, written, and digital modes of expression.</td>\n</tr>\n<tr>\n<td>3</td>\n<td width=\"527\">Critical Thinking: Possess intellectual inquiry and innovation enabling analysis and synthesis of social, political, economic, historical, geographical issues from multiple perspectives.&nbsp;&nbsp;</td>\n</tr>\n<tr>\n<td>4</td>\n<td width=\"527\">Research Skills: Develop interdisciplinary learning and research to address various social; national and global community level issues.</td>\n</tr>\n<tr>\n<td>5</td>\n<td width=\"527\">Analytical Reasoning: Apply empirical knowledge and develop scientific temperament to address social, political, economic, historical, geographical issues. Compare, classify, and analyze multiple perspectives, recognize underlying assumptions, and interpret data or arguments using logical reasoning.</td>\n</tr>\n<tr>\n<td>6</td>\n<td width=\"527\">Scientific Reasoning: Demonstrate scientific reasoning by applying logical, evidence-based, and systematic methods of inquiry to analyse complex human phenomena, texts, cultural practices, and socio-historical processes</td>\n</tr>\n<tr>\n<td>7</td>\n<td width=\"527\">Moral and Ethical awareness: Demonstrate sensitivity towards issues of national security, social justice, human rights, gender equality, diversity and inclusion, and make informed judgments grounded in democratic ethos, ethical, constitutional principles and good citizenship.</td>\n</tr>\n<tr>\n<td>8</td>\n<td width=\"527\">Social Interactive Skills, team work and Leadership qualities: Stimulate constructive social Interactions, inculcate social responsibility through fieldwork, community engagement, social work and develop leadership.</td>\n</tr>\n<tr>\n<td>9</td>\n<td width=\"527\">Lifelong Learning: Cultivate attitudes of lifelong learning, adaptability and preparing for higher studies, employment, public service, and on larger scale social engagement.</td>\n</tr>\n</tbody>\n</table>\n<hr />\n<h4><strong>Program Specific Outcomes (PSOs) :&nbsp;</strong></h4>\n<p>PSO 1: Historical Knowledge and Understanding</p>\n<p>Acquire comprehensive knowledge of Indian and World History across different periods and understand historical events, processes, institutions, and cultural developments in their social, political, economic, and cultural contexts.</p>\n<p>PSO 2: Critical Thinking and Research Skills</p>\n<p>Develop the ability to critically analyze historical events, interpret primary and secondary sources, apply historical research methods, and present evidence-based arguments.</p>\n<p>PSO 3: Heritage, Ethics, and Citizenship</p>\n<p>Appreciate and preserve cultural heritage, promote constitutional and ethical values, and &nbsp;predict future with thehelp of historical knowledgedemonstrate social responsibility by applying historical understanding to contemporary issues.</p>\n<hr />\n<h4><strong>Program Educational Objectives (PEOs) :</strong></h4>\n<p>Graduates will apply historical knowledge, critical thinking, research, communication, and heritage-management skills to pursue careers in teaching, civil services, research, &nbsp;and lawmuseums, archives, libraries, tourism, journalism, media, cultural heritage, and related fields, while demonstrating ethical and responsible citizenship.</p>\n<hr />\n<h4><strong>Course Outcomes (COs) :</strong></h4>\n<table style=\"border-collapse: collapse; width: 100%;\" border=\"1\">\n<tbody>\n<tr>\n<td style=\"width: 49.6102%;\">Class</td>\n<td style=\"width: 49.6102%;\">Download</td>\n</tr>\n<tr>\n<td style=\"width: 49.6102%;\">FYBA (NEP1.1)</td>\n<td style=\"width: 49.6102%;\"><a title=\"Course Outcome\" href=\"https://docs.google.com/document/d/1OeaiE0M2EnrepCJvk4MWALh3Ogbx6EYM/edit?usp=drive_web&amp;ouid=109944642474625076865&amp;rtpof=true\">Click Here</a></td>\n</tr>\n</tbody>\n</table>\n<hr />', '1', 0, 1, '', 166, '2026-10-14', 0),
